const a=[{day:1,phase:"awakening",title:"The Fish Discovers Water",subtitle:"You have never noticed your own mind",morningTeaching:{type:"concept",concept:"Autopilot Living",keyPoints:["You have spent your entire life reacting — not responding","The mind runs continuously without your permission or awareness","95% of daily behavior is unconscious habit","Today you will attempt something radical: simply noticing"],metaphor:"A fish swims its entire life without ever noticing water. You have lived inside your thoughts without ever noticing them. Today, for the first time, you look at the water.",scienceNote:"Neuroscience shows that up to 95% of brain activity is unconscious. The default mode network runs constantly, generating thoughts you never chose."},dayPractice:{type:"observation",instruction:`Set 3 alarms during your day. When each alarm rings, pause for 30 seconds and ask: "What was I just thinking?" Don't judge the thought. Just notice it exists.`,duration:"3 check-ins throughout the day",checkpoints:["What thought was running when the alarm went off?","Were you aware you were thinking before the alarm?","How does it feel to catch yourself in a thought?"]},eveningIntegration:{type:"reflection",prompt:"How many of your thoughts today did you actually choose? Were you thinking, or were thoughts just happening to you?",deeperPrompt:"If thoughts happen without your choosing — then who is doing the thinking? And who noticed that?",closingWisdom:"The moment you notice a thought, you have become bigger than it."},dimension:"awareness",relatedConcepts:["witness-gap","autopilot"]},{day:2,phase:"awakening",title:"The Thinker & The Watcher",subtitle:"There are two of you — which one are you?",morningTeaching:{type:"concept",concept:"The Witness",keyPoints:["There is the one who thinks — and the one who watches the thinking",'This "watcher" never changes, never reacts, never suffers',"You have always been the watcher pretending to be the thinker","Today you will practice being the watcher deliberately"],metaphor:"Imagine sitting in a movie theater. You have been so absorbed in the movie that you forgot you are in a seat, watching. Today, you feel the seat underneath you — while the movie continues."},dayPractice:{type:"witness",instruction:"Choose one routine activity (eating, walking, brushing teeth). During that activity, try to watch yourself doing it as if you were a camera observing a stranger. Notice everything — movements, sensations, thoughts about the activity.",duration:"One activity, done with full presence",checkpoints:['Could you maintain the "watching" for the whole activity?',"What happened when you forgot and went back to autopilot?",'Did you notice the moment you "woke up" again?']},eveningIntegration:{type:"reflection",prompt:"When you were watching yourself do the activity — who was watching? Can you sense that presence right now?",deeperPrompt:"Close your eyes. Thoughts are there. Sensations are there. But something else is there too — something still, something aware. Can you feel it?",closingWisdom:"You are not your thoughts. You are the space in which thoughts appear."},dimension:"awareness",relatedConcepts:["witness-gap","witness-depth"]},{day:3,phase:"awakening",title:"The River of Thoughts",subtitle:"Learning to sit on the bank instead of drowning",morningTeaching:{type:"deepening",concept:"Thought Observation",keyPoints:["Thoughts are like a river — they flow continuously","You have spent your life IN the river, carried by the current","Today you learn to sit on the bank and watch the river flow","You don't need to stop thoughts — just stop following them"],metaphor:"A river doesn't stop flowing because you sit on the bank. Thoughts won't stop because you observe them. But YOU are no longer drowning.",scienceNote:"The average person has 60,000-80,000 thoughts per day. Trying to stop them is futile. The practice is in changing your relationship to them."},dayPractice:{type:"observation",instruction:`For 5 minutes in the morning and 5 in the afternoon, sit quietly and watch your thoughts like clouds passing across a sky. Label each thought: "planning," "remembering," "worrying," "imagining." Don't engage — just label and let go.`,duration:"2 × 5-minute sessions",checkpoints:["What types of thoughts come most often?","Can you watch a thought without it pulling you in?","What happens in the gap between two thoughts?"]},eveningIntegration:{type:"witness-review",prompt:"Review your day from the perspective of the watcher — not the doer. What did you observe happening today?",deeperPrompt:"Did you notice any moment today where you were truly present — not in the past or future? What was that like?",closingWisdom:"Between every two thoughts, there is a gap. That gap is you."},dimension:"thought",relatedConcepts:["chitta-vritti","thought-patterns"]},{day:4,phase:"awakening",title:"The Body You Forgot",subtitle:"You live in your head — your body is waiting",morningTeaching:{type:"concept",concept:"Body Awareness",keyPoints:["Most people live entirely in their heads, disconnected from the body","Your body is always in the present moment — only the mind time-travels","The body stores information your mind ignores","Coming into the body is the fastest way to become present"],metaphor:"Your body is like an instrument you've never learned to play. It has been making music this whole time — heartbeat, breath, sensations — but you were too busy thinking to hear it."},dayPractice:{type:"body-scan",instruction:"Three times today, stop what you're doing. Close your eyes for 60 seconds. Scan your body from head to feet. Notice: Where is there tension? Warmth? Tingling? Numbness? Don't fix anything — just notice.",duration:"3 × 1-minute body scans",checkpoints:["Where in your body do you carry the most tension?","Can you feel your heartbeat without touching your chest?","What does your body feel like right now, in this exact moment?"]},eveningIntegration:{type:"body-release",prompt:"What did your body tell you today that your mind missed? Was there a moment your body reacted before your mind caught up?",deeperPrompt:"Right now, relax your jaw. Drop your shoulders. Unclench your hands. How long had they been tight without you knowing?",closingWisdom:"The body never lies. Only the mind has that ability."},dimension:"body",relatedConcepts:["somatic-awareness","gut-lens"]},{day:5,phase:"awakening",title:"The Emotional Weather",subtitle:"Feelings are visitors — not residents",morningTeaching:{type:"concept",concept:"Emotional Awareness",keyPoints:["Emotions change constantly like weather — but you treat them as permanent truths","An emotion lasts about 90 seconds — everything after that is you feeding it with thoughts","You don't need to understand an emotion to feel it fully","Suppression and expression are both reactions — awareness is the third way"],scienceNote:"Dr. Jill Bolte Taylor's research shows the physiological lifespan of an emotion is 90 seconds. After that, it requires renewed thought to sustain."},dayPractice:{type:"observation",instruction:'Every time you notice an emotion today — any emotion — pause for 3 seconds. Name it silently ("anger," "boredom," "excitement," "anxiety"). Then notice: Where do you feel it in your body? What thoughts accompany it? Then let it be.',duration:"Throughout the day, every emotional shift",checkpoints:["How many different emotions have you felt today?","Which emotion showed up most frequently?","Did naming the emotion change how it felt?"]},eveningIntegration:{type:"reflection",prompt:"What was the dominant emotion of your day? Was it one you chose, or one that happened to you?",deeperPrompt:"If you could feel ANY emotion right now, what would you choose? Now notice: what emotion is actually here? What's the gap between the two?",closingWisdom:"You are not angry — anger is visiting. You are the host, not the weather."},dimension:"emotion",relatedConcepts:["heart-lens","emotional-patterns"]},{day:6,phase:"awakening",title:"The Three Lenses",subtitle:"Head, Heart, and Gut — your internal committee",morningTeaching:{type:"concept",concept:"The Three Intelligence Centers",keyPoints:["You don't have one intelligence — you have three: Head (thinking), Heart (feeling), Gut (sensing)","Most people are dominated by one lens and ignore the others","The Head analyzes and plans, the Heart connects and values, the Gut protects and knows","True wisdom comes from all three in alignment"],metaphor:"Imagine three advisors in a room. The Head is the strategist, always calculating. The Heart is the empath, always feeling. The Gut is the bodyguard, always sensing danger. You have been listening to only one. Today you hear all three."},dayPractice:{type:"observation",instruction:"At three decision points today (even tiny ones like what to eat), pause and check all three lenses: HEAD — What does my mind think about this? HEART — What does my heart feel about this? GUT — What is my gut instinct?",duration:"3 decision points",checkpoints:["Which lens speaks loudest in you?","Which lens do you tend to ignore?","Were all three ever in agreement?"]},eveningIntegration:{type:"reflection",prompt:"Which of your three lenses dominated today? Head (overthinking), Heart (emotional), or Gut (reactive)?",deeperPrompt:"Think of a recent decision you regret. Which lens made that decision? Which lens was trying to warn you?",closingWisdom:"The truth is where all three lenses agree."},dimension:"awareness",relatedConcepts:["head-lens","heart-lens","gut-lens"]},{day:7,phase:"awakening",title:"The First Week Mirror",subtitle:"What did six days of watching reveal?",morningTeaching:{type:"review",concept:"Week 1 Integration",keyPoints:["You have done something most humans never do — turned attention inward","You met the Watcher, observed thoughts, felt the body, named emotions, and discovered three lenses","The fact that you can observe these things means you are NOT these things","Today is integration — not a new lesson, but a deepening of what you already know"]},dayPractice:{type:"journaling",instruction:`Write freely for 10 minutes. Start with: "In 6 days of watching, I discovered..." Don't censor, don't edit, don't perform. Write what is true.`,duration:"10 minutes",checkpoints:["What surprised you most this week?","What was hardest — watching thoughts, body, or emotions?","Have you noticed any shift in how you experience daily life?"]},eveningIntegration:{type:"integration",prompt:"If you could tell yourself from Day 1 one thing you've learned, what would it be?",deeperPrompt:"The person who started this journey 7 days ago — are they the same person reflecting right now? What changed?",closingWisdom:"Seven days of awareness creates more change than seven years of thinking about change."},dimension:"awareness",relatedConcepts:["witness-gap","observation"]},{day:8,phase:"awakening",title:"The Reactive Machine",subtitle:"You don't respond — you react. There's a difference.",morningTeaching:{type:"concept",concept:"Reactivity vs Response",keyPoints:["A reaction is automatic — it happens before you are aware","A response requires a gap — the gap between stimulus and action","Your entire personality is largely a collection of automatic reactions","Today you hunt for the gap — the space where freedom lives"],metaphor:"When someone cuts you off in traffic, do you choose to get angry? Or does anger choose you? The millisecond before the reaction is the most important moment of your life.",scienceNote:'Viktor Frankl: "Between stimulus and response, there is a space. In that space is our freedom and our power to choose our response."'},dayPractice:{type:"trigger-track",instruction:"Today, catch yourself reacting. Every time you feel a surge of emotion (irritation, defensiveness, excitement, craving), PAUSE. Count to 3. Then notice: what triggered this? Was the reaction proportional to the trigger?",duration:"Throughout the day",checkpoints:["How many times did you catch yourself reacting before you could pause?","Was there even ONE moment where you caught the reaction in time?",'What does the "gap" feel like when you find it?']},eveningIntegration:{type:"reflection",prompt:"What was your biggest reaction today? Was it truly about the situation, or about something older, deeper?",deeperPrompt:"Is there a reaction you have been having your whole life — the same pattern in different situations? Can you name it?",closingWisdom:"Freedom is not the absence of triggers — it is the presence of the gap."},dimension:"awareness",relatedConcepts:["witness-gap","loops","reactivity"]},{day:9,phase:"awakening",title:"The Story Machine",subtitle:"Your mind creates narratives about everything — none of them are reality",morningTeaching:{type:"concept",concept:"Mental Narratives",keyPoints:["Your mind is a storytelling machine — it creates stories about you, others, and the world","These stories feel like truth but they are interpretations, not facts","You live in your stories about reality, not in reality itself",'The story "I am not good enough" is as fictional as "once upon a time"'],metaphor:`You walk past a friend who doesn't say hello. Your mind writes a novel: "They're angry at me. What did I do? They've always been judgmental." Reality: they didn't see you. The entire drama happened only in your head.`},dayPractice:{type:"observation",instruction:'Catch THREE stories your mind creates today. When you notice an interpretation, label it: "Story." Then ask: "What actually happened?" Strip away all interpretation until only the bare facts remain.',duration:"3 story-catches",checkpoints:["What stories did your mind create about other people today?","What story does your mind tell about YOU most often?","Can you find the raw experience underneath the story?"]},eveningIntegration:{type:"neti-neti",prompt:'What is the biggest story your mind tells about who you are? ("I am successful/a failure/smart/broken") — is it TRUE, or just familiar?',deeperPrompt:"If you removed every story about yourself — every label, role, identity — what would be left?",closingWisdom:"The story is never the experience. Drop the story and meet life directly."},dimension:"thought",relatedConcepts:["mental-narratives","identity-band"]},{day:10,phase:"awakening",title:"Resistance: The Guard at the Door",subtitle:"Why your mind fights awareness — and what that means",morningTeaching:{type:"concept",concept:"Resistance to Awareness",keyPoints:["If you have been feeling resistance, boredom, or the urge to skip — good. That IS the lesson.","The mind resists awareness because awareness threatens the mind's control",'Resistance shows up as boredom, distraction, skepticism, sudden busyness, or "I already know this"',"The thing you resist looking at is exactly what needs to be seen"],scienceNote:"Psychological resistance is well-documented in therapy. The ego protects its structures by making awareness feel uncomfortable, boring, or pointless."},dayPractice:{type:"observation",instruction:"Today, don't fight resistance — study it. When you feel any urge to avoid, distract, check your phone, or skip awareness — THAT is the practice moment. Notice the resistance like you would notice a thought. What does resistance feel like in the body?",duration:"Throughout the day",checkpoints:["What is your mind's favorite distraction?","Can you feel resistance as a physical sensation?","What happens when you watch resistance without acting on it?"]},eveningIntegration:{type:"reflection",prompt:"What did you resist most today? Not what you think you should say — what is the honest answer?",deeperPrompt:"What if the thing you're most resistant to looking at is the exact thing that would set you free?",closingWisdom:"Resistance is not your enemy — it is a compass pointing directly at your growth."},dimension:"awareness",relatedConcepts:["resistance","defense-mechanisms"]},{day:11,phase:"awakening",title:"The Breath Bridge",subtitle:"The one thing that connects mind, body, and awareness",morningTeaching:{type:"concept",concept:"Breath as Anchor",keyPoints:["Breath is the only process that is both automatic AND voluntary","When you watch the breath, you bridge the gap between unconscious and conscious","Breath connects the mind to the body — it is the doorway between them","You don't need to control the breath — just watch it"],metaphor:"Breath is the bridge between the visible and invisible worlds. On one side: the body, matter, the seen. On the other: consciousness, awareness, the unseen. Your breath walks between them every moment.",scienceNote:"Conscious breathing activates the prefrontal cortex and reduces amygdala reactivity. It literally switches your brain from fight-or-flight to rest-and-observe."},dayPractice:{type:"breath-watch",instruction:'Three times today, watch your breath for 2 minutes. Do NOT control it. Do NOT breathe "correctly." Just watch. Notice: Is it shallow or deep? Fast or slow? Where do you feel it most — nose, chest, belly? What happens to your thoughts when you watch the breath?',duration:"3 × 2 minutes",checkpoints:["Did watching the breath change it? Could you watch without controlling?","What happened to your thoughts while watching the breath?","How does your body feel after 2 minutes of breath-watching?"]},eveningIntegration:{type:"body-release",prompt:"Right now, take 5 breaths with full attention. After the 5th breath — what do you notice?",deeperPrompt:"The breath breathes itself. You didn't start it, you can't stop it permanently. What else in your life is happening by itself while you think you're in control?",closingWisdom:"Watch the breath — and you watch the boundary between doing and being."},dimension:"body",relatedConcepts:["breath-awareness","presence"]},{day:12,phase:"awakening",title:"The Present Moment",subtitle:"The past is memory, the future is imagination — only NOW is real",morningTeaching:{type:"concept",concept:"Presence",keyPoints:["Your mind spends almost no time in the present — it oscillates between past and future","The past exists only as memory (thought). The future exists only as imagination (thought).","The ONLY moment that is ever real is this one","Suffering requires time — it requires past (regret) or future (anxiety). Presence has no suffering."],metaphor:"A dog doesn't live in regret about yesterday's walk or anxiety about tomorrow's meal. It is fully here. You were born with this ability — then you traded it for a mind that travels through time."},dayPractice:{type:"witness",instruction:"Set a single alarm for this afternoon. When it rings, stop. For 60 seconds, be fully in the present. Notice: 5 things you see, 4 things you hear, 3 things you feel (physically), 2 things you smell, 1 thing you taste. This is presence. This is reality.",duration:"1 deliberate presence exercise + spontaneous check-ins",checkpoints:["How much of your day was spent in past or future?","When you came into the present, did the quality of your experience change?","What is always here when you are truly present?"]},eveningIntegration:{type:"reflection",prompt:"What moment today were you most present? What moment were you most lost in thought?",deeperPrompt:"Right now, in this exact moment — do you have a problem? Not yesterday's problem, not tomorrow's worry. Right NOW — is there a problem?",closingWisdom:"The present moment is the only place where life actually happens. Everything else is the mind's movie."},dimension:"awareness",relatedConcepts:["presence","mindfulness"]},{day:13,phase:"awakening",title:"Identification: The Root Trap",subtitle:"You are identified with everything — that's why you suffer",morningTeaching:{type:"concept",concept:"Identification",keyPoints:['Identification = believing "I am THIS." I am my thoughts. I am my emotions. I am my body. I am my role.',"When you identify with something, its pain becomes YOUR pain, its threat becomes YOUR threat","A mother identifies with her child — if the child is hurt, SHE suffers. The mechanism is the same for all identification.","Dis-identification doesn't mean not caring — it means seeing clearly without being trapped"],metaphor:"You are wearing a costume so long you forgot it's a costume. Your name, your job, your personality, your beliefs — all costumes. Underneath them all, something unchanging remains."},dayPractice:{type:"observation",instruction:'Today, notice every time you say or think "I am..." — "I am tired," "I am angry," "I am not good at this." Reframe it: "Tiredness is present." "Anger is arising." "A thought about inadequacy appeared." Notice how the reframe changes the experience.',duration:"Throughout the day",checkpoints:['How many "I am" identifications did you catch?',"Did reframing change the intensity of the experience?",'What happens when you say "Sadness is here" instead of "I am sad"?']},eveningIntegration:{type:"neti-neti",prompt:'List 5 things you say "I am" to. Job, role, personality trait, emotion pattern. Now ask: were you this before age 5? Will you be this at 90? If it can change — is it really YOU?',deeperPrompt:"If you are not your thoughts, not your emotions, not your body, not your name, not your role — then what are you? Don't answer with the mind. Feel into it.",closingWisdom:"Everything you identify with will eventually be taken from you. What remains is who you truly are."},dimension:"awareness",relatedConcepts:["identity-band","dis-identification"]},{day:14,phase:"awakening",title:"The Door is Open",subtitle:"Phase 1 complete — you will never fully go back to sleep",morningTeaching:{type:"review",concept:"Phase 1 Completion",keyPoints:["In 14 days, you discovered: the witness, the three lenses, reactivity, stories, resistance, breath, presence, and identification","You cannot un-see what you have seen. Awareness is a one-way door.","From this point forward, even when you forget — you will remember that you forgot. That IS awareness growing.","Tomorrow begins Phase 2: The Mind Lens. You will go deep into the machinery that has been running your life."]},dayPractice:{type:"witness",instruction:"Today, integrate everything. Go through your normal day with one intention: WATCH. Don't try to observe thoughts specifically, or body, or emotions. Just be aware. Let awareness be like sunlight — illuminating whatever it touches without effort.",duration:"The entire day as practice",checkpoints:['How does "effortless awareness" feel compared to focused observation?',"What naturally draws your attention when you don't direct it?","Can you feel the witness as a stable presence behind all experience?"]},eveningIntegration:{type:"integration",prompt:"Write a letter to yourself about what these 14 days have shown you. Not what you learned intellectually — what you EXPERIENCED.",deeperPrompt:"The journey has barely begun. But the most important thing has already happened: you know you are asleep, and you want to wake up. Most humans live and die without ever having that realization.",closingWisdom:"The awakening is not the destination. It is the moment you realize you have been dreaming."},dimension:"awareness",relatedConcepts:["witness-depth","awareness-level"]}],s=[{day:15,phase:"mind",title:"The Thought Factory",subtitle:"Your mind produces 70,000 thoughts a day — how many did you order?",morningTeaching:{type:"concept",concept:"Involuntary Thought",keyPoints:["Thoughts arise without your permission — like breathing, but less useful","The mind is not a tool you use — it is a machine that uses you","Most thoughts are repetitive — the same 10 loops playing on repeat","Today: count your repetitive thoughts"]},dayPractice:{type:"observation",instruction:"Keep a mental tally. Every time you catch the SAME thought repeating (worry about work, replaying a conversation, planning something for the 5th time), notice it. By evening, see which thought repeated most.",duration:"Throughout the day",checkpoints:["What thought repeated most?","Were you surprised how repetitive the mind is?","What percentage of your thoughts were about the past vs future?"]},eveningIntegration:{type:"reflection",prompt:"What was your most repetitive thought today? If you played it on a billboard, would it be wise? Useful? True?",deeperPrompt:"If 90% of your thoughts are repetitive — who needs them? What would happen if they stopped?",closingWisdom:"The mind repeats because it believes repetition creates safety. It doesn't."},dimension:"thought",relatedConcepts:["thought-patterns","rumination"]},{day:16,phase:"mind",title:"Cognitive Biases",subtitle:"Your mind lies to you — and you believe it every time",morningTeaching:{type:"science",concept:"Cognitive Biases",keyPoints:["Confirmation bias: you only see evidence that supports what you already believe","Negativity bias: bad experiences weigh 5x more than good ones","Anchoring: the first piece of information shapes all subsequent thinking","These aren't character flaws — they're design features of the human mind"],scienceNote:"Daniel Kahneman's research shows that System 1 (fast, automatic) thinking contains over 180 documented cognitive biases. You are not rational — you are rationalizing."},dayPractice:{type:"trigger-track",instruction:'Today, watch for confirmation bias. When you form an opinion about something or someone, ask: "Am I seeing what IS, or seeing what I expect?" Try to find evidence that contradicts your first impression.',duration:"3 bias-catches",checkpoints:["Did you find an assumption you made that turned out wrong?","Can you catch your mind cherry-picking evidence?","How does it feel when you realize your mind filtered reality?"]},eveningIntegration:{type:"reflection",prompt:"What assumption did you catch today that was based on bias rather than reality?",deeperPrompt:'If your mind has been filtering reality through biases your whole life — how much of what you "know" about yourself is actually true?',closingWisdom:"The mind doesn't show you reality — it shows you a version of reality designed to confirm what you already believe."},dimension:"thought",relatedConcepts:["cognitive-biases","head-lens"]},{day:17,phase:"mind",title:"The Inner Critic",subtitle:"There's a voice that never stops judging — whose voice is it?",morningTeaching:{type:"concept",concept:"Inner Critic",keyPoints:["Almost everyone has a harsh internal voice that judges, criticizes, and compares","This voice usually belongs to a parent, teacher, or authority figure from childhood",'It was installed to keep you "safe" by keeping you small',"You don't need to fight it — you need to see it as a visitor, not as you"]},dayPractice:{type:"observation",instruction:`Today, every time you hear the inner critic ("you're stupid," "why did you do that," "you'll never..."), PAUSE. Write down what it said. Then ask: "Whose voice is this originally?"`,duration:"Throughout the day",checkpoints:["How many self-critical thoughts did you catch?","Did you recognize the voice as belonging to someone from your past?",'What happens when you see the critic as "a voice" rather than "truth"?']},eveningIntegration:{type:"reflection",prompt:"If you spoke to a friend the way your inner critic speaks to you, would you have any friends left?",deeperPrompt:"The inner critic believes it protects you by keeping you small. Thank it for trying — and choose to see yourself clearly instead.",closingWisdom:"The inner critic is a program running from childhood. You are not 5 years old anymore."},dimension:"thought",relatedConcepts:["inner-voices","shadow"]},{day:18,phase:"mind",title:"Judgment & Labeling",subtitle:"The mind labels everything — and every label is a prison",morningTeaching:{type:"concept",concept:"Mental Labeling",keyPoints:["The mind labels everything instantly: good/bad, right/wrong, like/dislike","These labels happen in milliseconds — before you can even see clearly","When you label something, you stop seeing it — you see only the label","Dropping labels doesn't mean losing discernment — it means seeing what IS"]},dayPractice:{type:"observation",instruction:"Choose one person you interact with today. Before every interaction, drop all labels: friend, colleague, annoying, nice. Look at them as if you are seeing a human being for the very first time. What do you notice that you normally miss?",duration:"1 person, all interactions",checkpoints:["What labels did you have to actively drop?","Did you see anything new about this person without the labels?","How does it feel to look at someone without judgment?"]},eveningIntegration:{type:"reflection",prompt:"What labels do you carry about yourself that might be preventing you from seeing who you really are?",deeperPrompt:"Is there anyone in your life you have completely reduced to a single label? What are you missing about them?",closingWisdom:"When you drop all labels, what remains is reality. And reality is always richer than any label."},dimension:"thought",relatedConcepts:["judgment","projection"]},{day:19,phase:"mind",title:"Rumination: The Mental Prison",subtitle:"The same thought, 10,000 times — each time believing it's new",morningTeaching:{type:"concept",concept:"Rumination",keyPoints:["Rumination is thinking about the same thing over and over without resolution",'It disguises itself as "processing" or "figuring things out" — but produces no insight',"Rumination is the mind's way of avoiding the FEELING underneath the thought","The cure is not more thinking — it is dropping into the body"],scienceNote:"Research shows rumination is the #1 predictor of depression — not life circumstances, not trauma, but the habit of repetitive negative thinking."},dayPractice:{type:"loop-catch",instruction:'Today, when you catch yourself ruminating (going over the same thing), STOP. Drop attention from the head into the body. Ask: "What am I FEELING right now?" Stay with the feeling for 30 seconds. Watch what happens to the rumination.',duration:"Every rumination loop",checkpoints:["How many times did you catch yourself ruminating?","What feeling was underneath the rumination?","Did moving to the body break the loop?"]},eveningIntegration:{type:"reflection",prompt:"What topic does your mind ruminate on most? What would happen if you simply stopped thinking about it and felt what's underneath?",deeperPrompt:"Rumination is the mind's way of maintaining the illusion of control. What are you trying to control that is fundamentally not in your control?",closingWisdom:"Thinking about a problem and feeling a problem are two different universes."},dimension:"thought",relatedConcepts:["rumination","MEN001","loops"]},{day:20,phase:"mind",title:"The Comparison Trap",subtitle:"Your mind measures you against everyone — and you always lose",morningTeaching:{type:"concept",concept:"Comparison",keyPoints:["The mind compares constantly: am I better/worse, richer/poorer, smarter/dumber","You compare your insides to other people's outsides",`Comparison is the mind's way of establishing your "rank" — a survival mechanism`,"There is no one to compare with because no one has your exact starting point, circumstances, or inner world"]},dayPractice:{type:"trigger-track",instruction:'Catch EVERY comparison today. On social media, at work, with friends. When you compare, ask: "What am I actually feeling right now?" Under comparison, there is always either fear or inadequacy. Find it.',duration:"Throughout the day",checkpoints:["How many times did you compare yourself to someone?","What emotion was underneath the comparison?","Did the comparison make you feel better or worse? For how long?"]},eveningIntegration:{type:"reflection",prompt:"Who did you compare yourself to today? What would your life be like if comparison simply stopped?",deeperPrompt:'Comparison requires TWO things: a self-image and a perceived "other." Both are mental constructs. Neither is real.',closingWisdom:"A rose never compares itself to a lotus. Both bloom in their own time."},dimension:"thought",relatedConcepts:["comparison","validation-loops"]},{day:21,phase:"mind",title:"The Mind in the Body",subtitle:"Week 2 Integration — bringing head awareness into the body",morningTeaching:{type:"review",concept:"Week 2 Integration",keyPoints:["You've mapped the Head Lens: repetitive thoughts, biases, inner critic, labels, rumination, comparison","Notice how ALL of these are patterns — not choices. The mind runs them automatically.","The head alone cannot free itself. It needs the other lenses.","This week, you start integrating mind observation with body sensation."]},dayPractice:{type:"body-scan",instruction:"Whenever a strong thought pattern arises today (criticism, comparison, worry), immediately scan your body. Where does that thought LIVE in your body? Throat tightness? Chest pressure? Stomach knot? Map at least 3 thoughts to body locations.",duration:"Throughout the day",checkpoints:["Where does worry live in your body?","Where does self-criticism live in your body?","Are you starting to see the mind-body connection?"]},eveningIntegration:{type:"integration",prompt:"Draw a simple body outline. Mark where each major thought pattern creates sensation. This is YOUR map.",deeperPrompt:"The body stores what the mind refuses to feel. What has YOUR body been storing?",closingWisdom:"The mind thinks, but the body knows."},dimension:"thought",relatedConcepts:["somatic-awareness","mind-body"]},{day:22,phase:"mind",title:"Future Anxiety",subtitle:"The mind creates problems that don't exist yet — and you suffer NOW",morningTeaching:{type:"concept",concept:"Anticipatory Anxiety",keyPoints:["The mind generates future scenarios — almost always negative","93% of worries never come true. Of the 7% that do, most are manageable.","When you worry, you suffer now for something that might never happen","The antidote is not positive thinking — it is returning to what IS, right now"],scienceNote:"Studies show that 85% of what people worry about never happens. Of the 15% that does, 79% said they handled it better than expected."},dayPractice:{type:"observation",instruction:'Every time you catch a "what if" thought today, write it down. Then ask: "Is this happening RIGHT NOW?" If no — notice that you are creating suffering about fiction. Return to this moment.',duration:"Throughout the day",checkpoints:['How many "what if" thoughts did you have?',"How many of them were about things happening right now?","What is the difference between genuine preparation and anxiety?"]},eveningIntegration:{type:"reflection",prompt:'Look at your "what if" list. How many of them are actually happening? How much energy did you spend on fiction today?',deeperPrompt:"If you couldn't think about the future for one day — would you be okay right now, in this exact moment?",closingWisdom:"The future doesn't need your worry. It needs your presence when it arrives."},dimension:"thought",relatedConcepts:["anxiety","presence"]},{day:23,phase:"mind",title:"Past Regret",subtitle:"Replaying what cannot be changed — the mind's favorite torture",morningTeaching:{type:"concept",concept:"Past Fixation",keyPoints:["The mind replays painful past events as if watching could change them","Regret is the mind's way of maintaining the illusion that you could have done differently — with who you WERE","You made every past decision with the awareness you had at the time. Period.","Forgiveness (of self and others) is not moral — it is practical. It ends the loop."]},dayPractice:{type:"observation",instruction:'Notice every time your mind goes to the past today — replaying, regretting, "if only." When it happens, say internally: "The past is complete." Feel your feet on the ground. Feel the present moment receive you.',duration:"Throughout the day",checkpoints:["What past event does your mind replay most?","Can you see that the person who made that choice is not the same person reflecting now?",'What happens when you say "The past is complete" — does something relax?']},eveningIntegration:{type:"reflection",prompt:"What past event are you still carrying? If you could truly release it — not forget it, but release the charge — how would your life change?",deeperPrompt:"Forgiveness is not about the other person — it is about releasing yourself from the prison of repetition.",closingWisdom:"Every moment you spend in the past is a moment stolen from the only life you have — this one."},dimension:"thought",relatedConcepts:["regret","forgiveness"]},{day:24,phase:"mind",title:"Beliefs: The Invisible Architecture",subtitle:"You don't see the world — you see your beliefs ABOUT the world",morningTeaching:{type:"concept",concept:"Core Beliefs",keyPoints:["Beliefs are not conclusions you reached — they are programs installed by experience","Most core beliefs were formed before age 7",'"I am not worthy," "The world is unsafe," "I must perform to be loved" — installed, not chosen',"A belief feels true because you have never questioned it"]},dayPractice:{type:"journaling",instruction:'Complete these sentences without thinking: "The world is..." "People are..." "I am..." "Love means..." "Success means..." "I must always..." — Write the FIRST thing that comes. These are your core beliefs.',duration:"15 minutes",checkpoints:["Were any of these beliefs surprising?","Can you trace any belief to a specific childhood experience?","Do any of your beliefs contradict each other?"]},eveningIntegration:{type:"neti-neti",prompt:`Pick one belief from today's exercise. Ask: "Is this mine, or was it installed in me?" Does the belief still serve you?`,deeperPrompt:"What if the most painful belief you carry is simply... untrue? What would change?",closingWisdom:"A belief is just a thought you've been thinking for so long that you forgot you could think differently."},dimension:"thought",relatedConcepts:["beliefs","core-beliefs","conditioning"]},{day:25,phase:"mind",title:"The Planning Mind",subtitle:"Always preparing for life instead of living it",morningTeaching:{type:"concept",concept:"Compulsive Planning",keyPoints:["The planning mind keeps you perpetually in the future","There is useful planning (logistics) and neurotic planning (avoiding uncertainty)","Neurotic planning is the mind's way of creating the illusion of control","Life cannot be fully planned — only met"]},dayPractice:{type:"observation",instruction:`Today, catch yourself planning. For EACH planning thought, ask: "Is this logistics or anxiety?" If it's logistics, continue. If it's anxiety disguised as planning, stop and feel the uncertainty underneath.`,duration:"Throughout the day",checkpoints:["How much of your planning was useful vs anxious?","What uncertainty are you trying to avoid through planning?","Can you sit with not-knowing for 60 seconds?"]},eveningIntegration:{type:"reflection",prompt:"What is the best thing that ever happened to you that you did NOT plan?",deeperPrompt:"What if uncertainty is not a bug but a feature — the space where surprise, growth, and grace enter your life?",closingWisdom:"The caterpillar cannot plan the butterfly. Some transformations require surrender."},dimension:"thought",relatedConcepts:["control","uncertainty"]},{day:26,phase:"mind",title:"Thought Gaps",subtitle:"The silence between notes is what makes music",morningTeaching:{type:"practice-intro",concept:"Accessing Thought Gaps",keyPoints:["Between every two thoughts, there is a gap — however brief","That gap is not emptiness — it is awareness without content","Most people are afraid of this gap because the mind equates silence with death","Today you actively seek the gap — the space between thoughts"]},dayPractice:{type:"witness",instruction:"Four times today, close your eyes for 2 minutes. Watch thoughts. But this time, don't follow the thoughts — watch for the SPACE between them. It may be a millisecond. That's enough. Try to notice the gap before the next thought begins.",duration:"4 × 2 minutes",checkpoints:["Did you find any gaps between thoughts?","What was the gap like? Empty? Spacious? Uncomfortable?","How does it feel to rest in the gap, even briefly?"]},eveningIntegration:{type:"reflection",prompt:`The gap between thoughts is who you are when you're not performing "you." What did you find there?`,deeperPrompt:"If the gap is always there — under every thought, behind every emotion — then what you truly are is never actually lost. Only overlooked.",closingWisdom:"You are not the thoughts. You are not even the thinker. You are the silence in which all thinking appears."},dimension:"thought",relatedConcepts:["witness-gap","thoughtless-awareness"]},{day:27,phase:"mind",title:"Mental Noise vs. Intelligence",subtitle:"The mind is useful — but only about 5% of the time",morningTeaching:{type:"concept",concept:"True Intelligence",keyPoints:["Intelligence is not the same as mental activity","True intelligence is silent — it appears as insight, not as noise","The mind at its best is a tool for practical problem-solving — nothing more","Everything else — rumination, comparison, anxiety — is the mind misusing itself"]},dayPractice:{type:"observation",instruction:"Today, categorize your thoughts into two buckets: USEFUL (solving a real, present problem) and NOISE (everything else — commentary, judgment, fantasy, worry). At the end, estimate the ratio.",duration:"Throughout the day",checkpoints:["What percentage of your thoughts were genuinely useful?","Did you notice that most useful thinking is calm, brief, and clear?","What is the quality of your best insights vs your noisiest thoughts?"]},eveningIntegration:{type:"reflection",prompt:"When did you use your mind brilliantly today — and when did it use you? What's the difference in how each felt?",deeperPrompt:"The greatest scientists, artists, and mystics all report that their best insights came in moments of silence — not thought. What does that tell you about the nature of true intelligence?",closingWisdom:"A clear mind is more intelligent than a busy mind. Silence is not the absence of intelligence — it is the source of it."},dimension:"thought",relatedConcepts:["mental-clarity","insight"]},{day:28,phase:"mind",title:"The Mind's Greatest Fear",subtitle:"What happens when thinking stops?",morningTeaching:{type:"concept",concept:"Fear of No-Mind",keyPoints:["The mind equates its cessation with YOUR death",'This is the deepest fear: "If I stop thinking, I will cease to exist"',"But every night in deep sleep, thinking stops — and you survive. You return.","The fear of no-mind IS the mind protecting itself — not you"]},dayPractice:{type:"silence",instruction:"Today, take 15 minutes of complete mental silence. Not meditation — just... stop. Sit somewhere. Don't focus on breath, don't observe thoughts. Just be. If the mind panics — watch the panic without engaging. Stay still.",duration:"15 minutes",checkpoints:["What happened when you tried to just... be?","Did the mind resist? How?","Was there any moment of actual peace beneath the panic?"]},eveningIntegration:{type:"reflection",prompt:"In deep sleep, your mind completely stops. Yet you wake up. You existed without thought. What does that tell you about who you really are?",deeperPrompt:'The mind says: "I think, therefore I am." What if the truth is: "I AM — and sometimes thinking happens within me"?',closingWisdom:"You survived every moment of silence you've ever experienced. The mind's fear is unfounded."},dimension:"thought",relatedConcepts:["no-mind","ego-death"]},{day:29,phase:"mind",title:"The Mind as a Tool",subtitle:"Not your enemy, not your master — your instrument",morningTeaching:{type:"concept",concept:"Right Relationship with Mind",keyPoints:["The mind is not to be killed, suppressed, or worshipped","It is a brilliant tool when used consciously and a tyrant when it runs unchecked","You want to be able to USE the mind and then set it down — like a hammer","A carpenter doesn't carry the hammer while eating dinner. You carry yours everywhere."]},dayPractice:{type:"observation",instruction:`Today, practice "picking up and setting down" the mind. When you need to think (work, planning, problem-solving), engage fully. When you don't need to think (walking, eating, showering), try to set the mind down. How often can you use it consciously?`,duration:"Throughout the day",checkpoints:[`How many times could you "set down" the mind when you didn't need it?`,"What activities required the mind vs which didn't?","Did you notice thinking continuing even when it wasn't needed?"]},eveningIntegration:{type:"reflection",prompt:"If you could only think when you chose to — and the rest of the time was peaceful stillness — how would your life change?",deeperPrompt:"The mind is the best servant and the worst master. Which has it been for you?",closingWisdom:"Use the mind. Don't be used by it."},dimension:"thought",relatedConcepts:["mental-mastery","conscious-thinking"]},{day:30,phase:"mind",title:"The Mind Phase Complete",subtitle:"You now see the machinery — tomorrow you learn to feel",morningTeaching:{type:"review",concept:"Phase 2 Completion",keyPoints:["In 16 days, you mapped the entire Mind Lens: thought patterns, biases, inner critic, beliefs, rumination, comparison, planning, gaps, noise, and fear","You now know your mind is a tool, not an identity","The next phase takes you into the Heart Lens — territory the mind cannot enter","Prepare to feel. The heart has its own intelligence."]},dayPractice:{type:"journaling",instruction:`Write a "Letter to My Mind." Tell it what you've learned about it. Thank it for its service. Set boundaries. Write from the part of you that is BIGGER than the mind.`,duration:"15 minutes",checkpoints:["What did you tell your mind?","How did it feel to write FROM awareness TO the mind?","Is there a relationship shift happening?"]},eveningIntegration:{type:"integration",prompt:"The mind is one lens. Tomorrow, the heart. What are you most curious about — and what are you most afraid of feeling?",deeperPrompt:"The mind understands. The heart KNOWS. These are different kinds of truth. Are you ready for the heart's truth?",closingWisdom:"The mind divides, the heart unites. You are about to cross the bridge."},dimension:"thought",relatedConcepts:["phase-transition","heart-lens"]}],r=[{day:31,phase:"heart",title:"Feeling vs. Thinking About Feeling",subtitle:"You have opinions about your emotions — today you actually feel them",morningTeaching:{type:"concept",concept:"Direct Emotional Experience",keyPoints:["Most people think ABOUT emotions rather than feeling them directly","Thinking about sadness and BEING with sadness are entirely different experiences",`The mind labels emotions to control them — "I understand why I'm angry" is not the same as feeling anger`,"Today you bypass the mind and go straight to the felt experience"]},dayPractice:{type:"observation",instruction:"Three times today, when you notice any emotion, STOP analyzing it. Instead: Where in your body is it? What is its temperature? Its texture? Its shape? Stay with the sensation for 60 seconds without naming or explaining.",duration:"3 emotional check-ins",checkpoints:["Could you feel the emotion without analyzing it?","What happened when you stayed with sensation instead of story?","Did the emotion shift or dissolve when you stopped thinking about it?"]},eveningIntegration:{type:"reflection",prompt:"What emotion visited you most today? Can you describe it in pure sensation terms — without using any emotion word?",deeperPrompt:"What if every emotion is the body trying to communicate something your mind doesn't want to hear?",closingWisdom:"Feel first. Understand later. The heart is faster than the mind."},dimension:"emotion",relatedConcepts:["heart-lens","emotional-body"]},{day:32,phase:"heart",title:"The 90-Second Rule",subtitle:"Every emotion has a natural lifespan — if you don't feed it",morningTeaching:{type:"science",concept:"Emotional Lifespan",keyPoints:["A pure emotion lasts approximately 90 seconds physiologically","After 90 seconds, it is YOUR THOUGHTS that sustain the emotion","Anger triggered by a thought can last hours because the thought keeps re-triggering","The practice: feel fully for 90 seconds, then watch what the mind does"],scienceNote:`Dr. Jill Bolte Taylor: "When a person has a reaction to something, there's a 90-second chemical process. After that, any remaining emotional response is the person choosing to stay in that emotional loop."`},dayPractice:{type:"observation",instruction:"When a strong emotion arises today, time it. Feel it fully without feeding it thoughts. After 90 seconds, notice: is the emotion still there on its own, or is the mind re-triggering it? Don't suppress — just observe.",duration:"Every strong emotion",checkpoints:["Did any emotion naturally dissolve within 90 seconds?","Could you catch the moment the mind re-ignited the emotion?","What does it feel like to let an emotion complete its cycle?"]},eveningIntegration:{type:"reflection",prompt:"What emotion lingered longest today? What thought was feeding it?",deeperPrompt:"If emotions naturally last 90 seconds, then emotional suffering is always a collaboration between the heart and the mind. Which one is leading in your case?",closingWisdom:"An emotion is a wave. Suffering is you holding the wave and refusing to let it crash."},dimension:"emotion",relatedConcepts:["emotional-processing","thought-emotion-cycle"]},{day:33,phase:"heart",title:"Emotional Suppression",subtitle:"What you push down doesn't disappear — it builds pressure",morningTeaching:{type:"concept",concept:"Suppression vs Awareness",keyPoints:[`Society teaches: "Don't cry," "Be strong," "Control your emotions"`,"This creates suppression — emotions pushed underground but not resolved","Suppressed emotions create physical symptoms, anxiety, and sudden outbursts","There are three responses to emotions: suppress, express, or WITNESS. Only witnessing transforms."]},dayPractice:{type:"observation",instruction:`Today, watch for suppression in yourself. When do you push feelings down? "I'm fine." "It doesn't bother me." "Whatever." These are suppression signals. When you catch one, ask: "What am I actually feeling right now?"`,duration:"Throughout the day",checkpoints:["How many times did you suppress or minimize a feeling?","What is your go-to suppression phrase?","What happened when you allowed yourself to actually feel what was there?"]},eveningIntegration:{type:"body-release",prompt:"Right now, scan your body. Is there stored tension from today? Jaw? Shoulders? Stomach? Let it speak. What emotion lives there?",deeperPrompt:"How many years of unfelt emotions are stored in your body right now? What would happen if you gave them permission to be felt?",closingWisdom:"The body keeps the score. Every unfelt emotion is stored as tension, pain, or disease."},dimension:"emotion",relatedConcepts:["suppression","somatic-storage"]},{day:34,phase:"heart",title:"The Emotional Map",subtitle:"Every emotion has a home address in your body",morningTeaching:{type:"practice-intro",concept:"Emotional Body Mapping",keyPoints:["Anger often lives in the jaw, fists, and solar plexus","Fear contracts the chest and belly","Sadness weighs on the chest and throat","Joy expands the heart and opens the shoulders","YOUR map may be different — today you discover it"]},dayPractice:{type:"body-scan",instruction:"Today, map at least 4 different emotions to body locations. When you feel anger — where? Sadness — where? Anxiety — where? Joy — where? Create your personal emotional body map.",duration:"Throughout the day",checkpoints:["Where does anger live in YOUR body?","Where does sadness live?","Where does joy live?","Are you starting to catch emotions through body signals BEFORE the mind labels them?"]},eveningIntegration:{type:"integration",prompt:"Draw your emotional body map. Mark where each emotion lives. This map is your early warning system — the body signals the emotion before the mind catches up.",deeperPrompt:"If you could sense emotions in the body before the mind labels them — you would have a choice before the reaction. This is emotional intelligence, not as a concept but as lived skill.",closingWisdom:"The body is always one step ahead of the mind. Learn to read it."},dimension:"emotion",relatedConcepts:["somatic-map","emotional-body"]},{day:35,phase:"heart",title:"Triggers: The Button Map",subtitle:"Other people don't create your emotions — they press buttons you installed",morningTeaching:{type:"concept",concept:"Emotional Triggers",keyPoints:["A trigger is an external event that activates a disproportionate emotional response","The trigger is never the cause — it activates a wound that already exists",'"They made me angry" is never true. They pressed a button — you built the button.',"Mapping your triggers reveals your unhealed wounds"]},dayPractice:{type:"trigger-track",instruction:"Today, every time you feel triggered (irritated, defensive, hurt, reactive), write down: (1) What happened (2) What emotion arose (3) How intense it was (1-10) (4) Does this REMIND you of anything from childhood?",duration:"Throughout the day",checkpoints:["What triggered you today?","Was the reaction proportional to the event?","Could you trace the trigger to an older wound?"]},eveningIntegration:{type:"reflection",prompt:"Look at your trigger map. What pattern do you see? Is there a core wound underneath multiple triggers?",deeperPrompt:"The people who trigger you most are your greatest teachers — because they show you exactly where your unhealed wounds are. Who triggers you most, and what are they showing you?",closingWisdom:"No one can press a button that doesn't exist. Find your buttons — and you find your freedom."},dimension:"emotion",relatedConcepts:["triggers","emotional-patterns","wounds"]},{day:36,phase:"heart",title:"Anger: The Guardian",subtitle:"Anger is not the problem — it's protecting something precious",morningTeaching:{type:"concept",concept:"Anger as Messenger",keyPoints:["Anger always protects something — a boundary, a value, a vulnerability","Under every anger is either hurt, fear, or a crossed boundary","Expressing anger damages relationships. Suppressing it damages you. Witnessing it transforms.","Today you meet anger as a messenger, not an enemy"]},dayPractice:{type:"observation",instruction:`If anger arises today (even mild irritation), don't act on it and don't suppress it. Ask: "What is this anger protecting?" Feel underneath the anger. What's there? Hurt? Fear? A boundary being crossed?`,duration:"When anger/irritation arises",checkpoints:["Did anger appear today? What was underneath it?","What was the anger trying to protect?","Can you honor the message without the destruction?"]},eveningIntegration:{type:"reflection",prompt:"What do you do with anger? Explode? Suppress? Turn it inward? What would happen if you just... stayed with it?",deeperPrompt:"Is there an anger you've been carrying for years? What is it still trying to protect? Does it still need protecting?",closingWisdom:"Anger is not fire. It is the alarm. Find what it's alarming you about."},dimension:"emotion",relatedConcepts:["anger","boundaries","defense-mechanisms"]},{day:37,phase:"heart",title:"Fear: The Primal Gate",subtitle:"Fear is not real — danger is. Learn the difference.",morningTeaching:{type:"concept",concept:"Fear as Illusion",keyPoints:["Fear of a tiger is useful. Fear of a job interview uses the same brain circuitry — but the tiger isn't there.","Most fear is anticipatory — about something that hasn't happened yet","The body cannot tell the difference between imagined danger and real danger","When you face fear with awareness, it becomes energy. When you flee, it becomes anxiety."]},dayPractice:{type:"observation",instruction:'Today, track fear in all its forms: anxiety, nervousness, avoidance, procrastination (procrastination IS fear). When you catch it, ask: "What is the worst that could actually happen?" Then: "Could I handle that?"',duration:"Throughout the day",checkpoints:["What fears showed up today?","Were any of them about present-moment danger?",'What happened when you asked "Could I handle the worst case?"']},eveningIntegration:{type:"reflection",prompt:"What is your deepest fear? Not about situations — about yourself? Fear of being unlovable? Alone? Not enough? Can you name it?",deeperPrompt:"Every fear, traced to its root, leads to one of three: fear of death, fear of abandonment, or fear of inadequacy. Which is yours?",closingWisdom:"You have survived 100% of everything that has ever happened to you. Your track record is perfect."},dimension:"emotion",relatedConcepts:["fear","anxiety","survival-loops"]},{day:38,phase:"heart",title:"Sadness: The Door to Depth",subtitle:"Sadness is not weakness — it's the heart doing its deepest work",morningTeaching:{type:"concept",concept:"Sacred Sadness",keyPoints:["Society pathologizes sadness — but sadness is the heart's response to loss, change, and truth","Sadness opens you — anger closes you. Which one does your growth require?","Underneath chronic busy-ness, many people carry unfelt sadness","Tears are not breakdown — they are the heart's way of releasing what no longer serves"]},dayPractice:{type:"observation",instruction:"Today, give yourself permission to feel sadness if it arises. Don't fix it, don't cheer up. When sadness visits, sit with it for 2 minutes. What is it grieving? What does it want to release?",duration:"When sadness arises naturally",checkpoints:["Did sadness appear today? What triggered it?","Could you stay with it without trying to fix it?","What did the sadness want to tell you?"]},eveningIntegration:{type:"reflection",prompt:"When was the last time you cried? What does your relationship with tears tell you about your relationship with vulnerability?",deeperPrompt:"Is there a grief you've been carrying — for a loss, a dream, a version of yourself that didn't happen? Can you give it space tonight?",closingWisdom:"The heart that has never been broken is the heart that has never been fully open."},dimension:"emotion",relatedConcepts:["grief","vulnerability","emotional-depth"]},{day:39,phase:"heart",title:"Joy: The Forgotten Emotion",subtitle:"You are addicted to problems — joy makes you nervous",morningTeaching:{type:"concept",concept:"Upper Limit Problem",keyPoints:['Most people have an unconscious "set point" for how much joy they allow themselves',"When things go TOO well, the mind creates problems to bring you back to familiar discomfort",'This is the "Upper Limit Problem" — you sabotage your own happiness because it feels unsafe',"Joy is not earned — it is allowed"],scienceNote:`Gay Hendricks' research on the "Upper Limit Problem" shows that most people unconsciously create conflicts, worries, or physical symptoms when they exceed their joy tolerance.`},dayPractice:{type:"observation",instruction:`Today, watch for joy — and watch what happens TO it. When something good happens, how long can you stay with the good feeling before your mind introduces a worry, a "but," or a "it won't last"?`,duration:"Throughout the day",checkpoints:["Did you catch the mind limiting your joy?","What is your joy tolerance — how many minutes of happiness before worry returns?","What would happen if you let joy be, without monitoring it?"]},eveningIntegration:{type:"gratitude-deep",prompt:"Name three moments today that were genuinely good. How long did you allow yourself to enjoy them before the mind intervened?",deeperPrompt:"What if you are not designed for suffering? What if joy is not a reward for pain, but your natural state when the mind gets quiet?",closingWisdom:"You don't need to earn joy. You need to stop blocking it."},dimension:"emotion",relatedConcepts:["upper-limit","joy","self-sabotage"]},{day:40,phase:"heart",title:"Emotional Alchemy",subtitle:"Every emotion is energy — and energy can be transformed",morningTeaching:{type:"concept",concept:"Emotional Transformation",keyPoints:['Emotions are not "positive" or "negative" — they are different qualities of energy',"Anger is fire energy — it can destroy or it can forge. Fear is alert energy — it can paralyze or sharpen.","The same emotional energy that causes suffering can be transmuted into creativity, compassion, or presence","Alchemy: feel the emotion without the story, and the energy becomes available for conscious use"]},dayPractice:{type:"witness",instruction:'Today, when a strong emotion arises, try this: Feel it fully. Drop the story. Stay ONLY with the raw energy. Then ask: "If this energy had no label, what could I do with it?" Notice how the same energy can shift its quality.',duration:"When strong emotions arise",checkpoints:["Could you separate the energy from the story?","What happened to the emotion when you dropped the narrative?","Did you experience the energy transforming?"]},eveningIntegration:{type:"integration",prompt:"What emotional energy did you transform today? What did it become when you removed the story?",deeperPrompt:"The yogis say all emotions are distortions of one energy: consciousness itself. Anger is distorted awareness, fear is distorted attention, sadness is distorted acceptance. Can you sense this?",closingWisdom:"You don't need fewer emotions — you need clearer eyes to see what they really are."},dimension:"emotion",relatedConcepts:["emotional-alchemy","transmutation"]},{day:41,phase:"heart",title:"Empathy & Boundaries",subtitle:"Feeling everything is not empathy — it's drowning",morningTeaching:{type:"concept",concept:"Conscious Empathy",keyPoints:["Empathy without boundaries becomes enmeshment — you lose yourself in others' emotions","True empathy is sensing another's experience without losing your center",'Many "empaths" are actually people-pleasers or boundary-avoidant',"You can be compassionate AND boundaried — these are not opposites"]},dayPractice:{type:"mirror",instruction:"Today, in one interaction, practice conscious empathy: sense what the other person is feeling, but stay aware of YOUR body. Notice: is this MY emotion or theirs? Can I witness their pain without taking it into my body?",duration:"1-2 interactions",checkpoints:["Could you sense their emotion without absorbing it?","Where is the line between empathy and absorption?","How does it feel to be compassionate without losing yourself?"]},eveningIntegration:{type:"reflection",prompt:"Whose emotions do you carry that aren't yours? Parent? Partner? Friend? What would happen if you lovingly gave them back?",deeperPrompt:"The greatest act of love is not absorbing someone's pain — it is staying so present and grounded that your presence itself becomes healing.",closingWisdom:"You cannot pour from an empty cup, and you cannot heal by bleeding."},dimension:"emotion",relatedConcepts:["empathy","boundaries","codependency"]},{day:42,phase:"heart",title:"The Heart's Intelligence",subtitle:"Week 6 Integration — the heart knows what the mind cannot grasp",morningTeaching:{type:"review",concept:"Heart Phase Integration",keyPoints:["You've mapped the Heart Lens: direct feeling, 90-second rule, suppression, triggers, anger, fear, sadness, joy, alchemy, empathy","The heart's intelligence is relational — it knows through connection, not analysis","You now have two lenses calibrated: Head and Heart","The next 3 days deepen heart practice before moving to the Body"]},dayPractice:{type:"journaling",instruction:"Write a letter FROM your heart TO your mind. What does your heart want your mind to know? What has the heart been trying to say that the mind keeps overriding?",duration:"15 minutes",checkpoints:["What did your heart say to your mind?","Was there a message the mind had been blocking?","How does it feel to give the heart a voice?"]},eveningIntegration:{type:"integration",prompt:"In the dance between head and heart — who leads in your life? Who should lead?",deeperPrompt:"The heart doesn't think in words — it speaks in feelings, sensations, and knowings. Can you feel it speaking right now?",closingWisdom:"The mind can take you to the door. Only the heart can walk through it."},dimension:"emotion",relatedConcepts:["heart-intelligence","emotional-wisdom"]},{day:43,phase:"heart",title:"Vulnerability: The Strength You Fear",subtitle:"The strongest armor is also the thickest prison",morningTeaching:{type:"concept",concept:"Conscious Vulnerability",keyPoints:["Vulnerability is not weakness — it is the courage to be seen as you are","Every defense you built to protect yourself also prevents connection","The people you love most are the ones you let see you undefended","Today you practice the radical act of dropping one wall"]},dayPractice:{type:"observation",instruction:'Today, in one safe interaction, share something slightly more honest than usual. Not dramatic — just one degree more real. "I actually feel nervous about this" or "That meant a lot to me." Notice what happens.',duration:"1 vulnerable moment",checkpoints:["What did you share that was more honest than usual?","How did it feel? Terrifying? Freeing? Both?","How did the other person respond?"]},eveningIntegration:{type:"reflection",prompt:"What is the one thing you are most afraid for people to know about you? Not your secret — your vulnerability. Can you hold it with compassion?",deeperPrompt:"What if the thing you're hiding is the thing that would most deeply connect you with others?",closingWisdom:"The crack is where the light gets in."},dimension:"emotion",relatedConcepts:["vulnerability","authenticity","defense-mechanisms"]},{day:44,phase:"heart",title:"Love Without Conditions",subtitle:"Can you love without needing anything in return?",morningTeaching:{type:"concept",concept:"Unconditional Love",keyPoints:['Most love is conditional: "I love you IF you behave, agree, stay, perform"',"Conditional love is a transaction. Unconditional love is a state of being.","You don't need to love everyone unconditionally — start with yourself","Self-love is not narcissism — it is the absence of self-attack"]},dayPractice:{type:"observation",instruction:`Today, practice unconditional regard toward yourself. Every time the inner critic speaks, respond: "I see this part of me, and I don't reject it." Not fixing, not improving — just... accepting what is.`,duration:"Throughout the day",checkpoints:["How many times did you choose acceptance over self-criticism?","How does it feel to NOT reject a part of yourself?","Is there a part you still can't accept? That's okay — just notice."]},eveningIntegration:{type:"reflection",prompt:"What part of yourself do you still reject? What would it take to hold even that with kindness?",deeperPrompt:"Can you love yourself even on your worst day? Not because you're perfect, but because you're human?",closingWisdom:"You cannot love another more than you love yourself. Self-rejection is the root of all relationship pain."},dimension:"emotion",relatedConcepts:["self-love","unconditional","acceptance"]},{day:45,phase:"heart",title:"The Heart Phase Complete",subtitle:"You learned to think in Phase 2. You learned to feel in Phase 3. Now — the body.",morningTeaching:{type:"review",concept:"Phase 3 Completion",keyPoints:["15 days of heart work: direct feeling, the 90-second rule, triggers, anger, fear, sadness, joy, alchemy, vulnerability, love","You now have two calibrated lenses and can observe both thoughts AND emotions","The next phase — the Body — completes the three-lens system","The body holds the oldest wisdom and the deepest pain. Prepare."]},dayPractice:{type:"witness",instruction:"Today, balance all three so far: Watch thoughts arise. Feel emotions move. Sense the body holding both. All at once. This is multi-dimensional awareness. How long can you sustain it?",duration:"Throughout the day",checkpoints:["Could you hold awareness of thoughts AND emotions AND body simultaneously?","Which lens slipped first when you tried?","What does triple-awareness feel like?"]},eveningIntegration:{type:"integration",prompt:"Head, Heart, Body — three intelligences. You've met two. The body is next. What is your body already trying to tell you that you haven't listened to?",deeperPrompt:"The body never lies. The mind lies constantly. The heart can be confused. But the body? It always tells the truth. Are you ready to listen?",closingWisdom:"Tomorrow, you come home to the body. It has been waiting for you your entire life."},dimension:"emotion",relatedConcepts:["three-lenses","integration","body-transition"]}],h=[{day:46,phase:"body",title:"Coming Home to the Body",subtitle:"You've been living in your head — the body has been running alone",morningTeaching:{type:"concept",concept:"Somatic Intelligence",keyPoints:['You have been a "head on a stick" — intellect disconnected from body',"The body processes information 100x faster than conscious thought","Gut feelings are real — the enteric nervous system has 100 million neurons","Somatic awareness is the foundation of intuition, safety, and truth-detection"],scienceNote:`The gut contains 100 million neurons (the enteric nervous system) and produces 95% of the body's serotonin. "Gut feeling" is literal neuroscience, not metaphor.`},dayPractice:{type:"body-scan",instruction:"Do a full body scan 4 times today: once after waking, once mid-morning, once afternoon, once before this session. Scan head to feet. Don't try to relax anything — just MAP what's there. Where is tension? Warmth? Numbness? Aliveness?",duration:"4 × 3-minute scans",checkpoints:["Which part of your body carries the most tension?","Is there an area you can't feel at all (numbness)?","Did the body map change through the day?"]},eveningIntegration:{type:"body-release",prompt:"Right now, tense every muscle in your body for 10 seconds. Then release completely. What remains? That residual tension is what you've been carrying unconsciously.",deeperPrompt:"The body stores every unfelt emotion, every swallowed word, every avoided confrontation. It's all in there. Your body scan is the beginning of an archaeological dig.",closingWisdom:"The body is always in the present moment. When you come home to the body, you come home to now."},dimension:"body",relatedConcepts:["gut-lens","somatic-intelligence"]},{day:47,phase:"body",title:"Tension Archaeology",subtitle:"Every knot in your body has a story",morningTeaching:{type:"deepening",concept:"Stored Trauma in the Body",keyPoints:["Chronic tension patterns are emotional fossils — preserved reactions from the past","Tight jaw often = words never spoken. Tight shoulders = burden carried. Tight belly = fear held.",`The body doesn't "forget" — it stores what the mind won't process`,"You don't need to relive trauma to release it — awareness alone begins the unwinding"],scienceNote:`Bessel van der Kolk's research: "The body keeps the score." Trauma is stored not in narrative memory but in somatic memory — muscle tension, breathing patterns, and nervous system states.`},dayPractice:{type:"body-scan",instruction:`Focus on your TOP 3 tension areas today. For each one: place your hand there, breathe into it, and ask (without forcing an answer): "What are you holding?" Stay for 2 minutes per area. Don't expect dramatic revelations — just listen.`,duration:"3 × 2-minute focused awareness",checkpoints:['Did any tension area "speak" when you gave it attention?',"Did any memory or emotion surface?","Did the tension change at all from the attention?"]},eveningIntegration:{type:"body-release",prompt:`Your body has been holding things you wouldn't let yourself feel. Tonight, give it permission to soften. Lie down, breathe, and silently say to your body: "I'm listening now."`,deeperPrompt:"What is the oldest tension in your body? Can you trace it back to when it first appeared?",closingWisdom:"The body doesn't need fixing. It needs witnessing."},dimension:"body",relatedConcepts:["somatic-storage","trauma","body-holding-patterns"]},{day:48,phase:"body",title:"The Gut Brain",subtitle:"Your belly knows before your head — learn to trust it",morningTeaching:{type:"science",concept:"Gut Intelligence",keyPoints:['The gut has its own nervous system — the "second brain"',"Gut feelings arrive faster than conscious thought because they bypass the analytical mind","The gut is your primary safety system — it senses danger before the mind can reason","Most people override gut signals with head logic — and regret it"]},dayPractice:{type:"observation",instruction:"Today, before EVERY decision (even tiny ones), check your gut first. Hand on belly. What does the gut say? Expansion (yes) or contraction (no)? Then notice: does your head agree or override the gut?",duration:"Every decision point",checkpoints:["How often did gut and head agree?","When they disagreed, which was right in hindsight?","Can you feel the difference between gut expansion and contraction?"]},eveningIntegration:{type:"reflection",prompt:"Think of a major decision you made that went wrong. Did your gut try to warn you? What did the head say that overrode it?",deeperPrompt:"The gut doesn't explain — it just knows. Can you trust knowing without understanding?",closingWisdom:"When the gut says no and the head says yes — the gut is almost always right."},dimension:"body",relatedConcepts:["gut-lens","intuition","gut-brain"]},{day:49,phase:"body",title:"Breath Patterns & Emotional States",subtitle:"Show me how you breathe and I'll show you how you live",morningTeaching:{type:"concept",concept:"Breath as Mirror",keyPoints:["Your breathing pattern mirrors your emotional state perfectly","Anxiety = shallow, rapid chest breathing. Calm = slow, deep belly breathing.","You can read your own emotional state by checking your breath — instant feedback","Changing the breath changes the emotion (but watching it without changing is the deeper practice)"]},dayPractice:{type:"breath-watch",instruction:"Check your breath 5 times today at random moments: Is it shallow or deep? Fast or slow? In the chest or belly? Held or flowing? Don't change it — just note what it reveals about your current state.",duration:"5 breath check-ins",checkpoints:["What was your most common breathing pattern today?","Did breath change based on your emotional state?","Were you holding your breath at any point? When?"]},eveningIntegration:{type:"body-release",prompt:"Right now, breathe normally and watch. Where does your breath live — high in the chest or deep in the belly? That's your default. What does it tell you about your baseline state?",deeperPrompt:"A baby breathes with its entire body. You breathe with the top 30% of your lungs. When did you learn to breathe small?",closingWisdom:"The quality of your breath is the quality of your life."},dimension:"body",relatedConcepts:["breath-patterns","nervous-system"]},{day:50,phase:"body",title:"Halfway Point: The Body of Awareness",subtitle:"Day 50 of 118 — your awareness now has three roots",morningTeaching:{type:"review",concept:"Halfway Integration",keyPoints:["50 days in. You have calibrated three lenses: Head, Heart, and Gut","You can now observe thoughts, feel emotions, and sense the body — often simultaneously","This triple-awareness is rare. Most humans have zero lenses calibrated.","The second half of the journey goes deeper: patterns, inquiry, energy, and integration"]},dayPractice:{type:"witness",instruction:"Today is a celebration of awareness. Go through your day with all three lenses open: watching thoughts, feeling emotions, sensing the body. Don't force it. Let awareness be natural, like breathing. When you forget, smile and return.",duration:"The entire day",checkpoints:["Can you hold triple-awareness for 5 minutes? 10?","What pulls you out of awareness most reliably?","How different is today from Day 1?"]},eveningIntegration:{type:"integration",prompt:"Write about your journey so far. 50 days. Where were you? Where are you now? Be honest about both growth and struggle.",deeperPrompt:"You are exactly halfway. The first half built the instruments. The second half uses them to see what has been invisible. Are you ready to see?",closingWisdom:"You didn't learn awareness. You remembered it. It was always there — you just stopped looking away."},dimension:"awareness",relatedConcepts:["three-lenses","halfway","triple-awareness"]},{day:51,phase:"body",title:"Movement as Meditation",subtitle:"Stillness is not the only door — the body moves into presence too",morningTeaching:{type:"concept",concept:"Conscious Movement",keyPoints:["Most meditation traditions emphasize stillness, but the body is designed to move","Walking, stretching, even washing dishes can be meditation — if done with awareness","The key is not the activity but the QUALITY OF ATTENTION you bring to it","Movement breaks the thinking loop because the body demands present-moment attention"]},dayPractice:{type:"observation",instruction:"Choose one physical activity today (walking, cooking, exercising). Do it with total awareness: feel every micro-movement, every muscle engagement, the weight of your body. Let the activity BE the meditation.",duration:"20 minutes of conscious movement",checkpoints:["Could you sustain awareness during movement?","How is moving meditation different from sitting meditation?","Did the mind quiet more easily when the body was engaged?"]},eveningIntegration:{type:"reflection",prompt:"When your body moves with full awareness, where does the mind go? Does it quiet down, or does it resist?",deeperPrompt:"What if your most mundane physical activities — walking, eating, cleaning — became your deepest practice? No special time needed. Just presence.",closingWisdom:'Zen saying: "Before enlightenment, chop wood, carry water. After enlightenment, chop wood, carry water." — but consciously.'},dimension:"body",relatedConcepts:["conscious-movement","kinetic-meditation"]},{day:52,phase:"body",title:"Pain & Resistance",subtitle:"Pain is a signal — suffering is the story about the signal",morningTeaching:{type:"concept",concept:"Pain vs Suffering",keyPoints:["Pain is physical/emotional sensation. Suffering is the mental resistance to that sensation.","Pain × Resistance = Suffering. Remove resistance and suffering drops — even if pain remains.",`The mind makes pain worse by adding: "Why me?", "This shouldn't happen", "It will never end"`,"Breathe INTO pain instead of away from it — watch what shifts"]},dayPractice:{type:"body-scan",instruction:"Find a minor physical discomfort today (tension, headache, soreness). Instead of ignoring or fixing it, breathe INTO it. Give it attention. Describe its exact qualities: sharp/dull, pulsing/constant, hot/cold. Stay with it for 3 minutes. What happens?",duration:"1 pain-attention exercise",checkpoints:["Did the pain change when you gave it full attention?","Could you separate the sensation from the story about it?","What resistance did you notice?"]},eveningIntegration:{type:"reflection",prompt:"Where in your life are you suffering not because of what IS, but because of your resistance to what is?",deeperPrompt:`Pain says: "Pay attention here." Suffering says: "This shouldn't be." One is a teacher. The other is a prison. Which do you engage with more?`,closingWisdom:"What you resist persists. What you embrace dissolves."},dimension:"body",relatedConcepts:["pain-body","resistance","surrender"]},{day:53,phase:"body",title:"The Nervous System States",subtitle:"Fight, flight, freeze, or flow — where do you live?",morningTeaching:{type:"science",concept:"Polyvagal Theory Basics",keyPoints:["Your nervous system has three primary states: ventral vagal (safe/connected), sympathetic (fight/flight), dorsal vagal (freeze/collapse)","Most people live primarily in sympathetic activation — always slightly on alert","You can learn to read which state you're in by body signals","Awareness itself activates the ventral vagal — the safe and connected state"],scienceNote:`Stephen Porges' Polyvagal Theory shows the vagus nerve mediates between danger responses and social engagement. Conscious body awareness activates the "social engagement" branch, promoting safety.`},dayPractice:{type:"body-scan",instruction:"Check your nervous system state 4 times today. Ask: Am I in fight (tension, anger), flight (anxiety, restlessness), freeze (numbness, overwhelm), or flow (calm, connected)? Just notice — don't try to change.",duration:"4 nervous system check-ins",checkpoints:["What is your default nervous system state?","What triggers you into fight/flight?",'When are you most in "flow"?']},eveningIntegration:{type:"reflection",prompt:'What percentage of your day was spent in each state? What would your life be like if you could consciously return to "flow" more often?',deeperPrompt:"The nervous system state you lived in as a child becomes your adult default. What was your childhood nervous system state? Is it still running the show?",closingWisdom:"Your nervous system is not broken — it is brilliantly adapted to a threat that no longer exists."},dimension:"body",relatedConcepts:["nervous-system","polyvagal","safety"]},{day:54,phase:"body",title:"Somatic Intuition",subtitle:"The body whispers before the mind shouts",morningTeaching:{type:"concept",concept:"Body Intuition",keyPoints:["The body gives signals BEFORE conscious awareness — goosebumps, gut contraction, heart opening","These signals are your most reliable intelligence source","Intuition is not mystical — it is the body processing millions of data points below conscious threshold","Learning to trust body signals is the highest practical intelligence"]},dayPractice:{type:"observation",instruction:"Today, before responding to any request, question, or situation — pause and check the body first. What is the BODY's response before the mind formulates an answer? Hand on belly. Heart open or closed? Body expanding or contracting?",duration:"Throughout the day",checkpoints:["Did the body give you useful information the mind missed?",'Is there a consistent body signal for "yes" vs "no" for you?',"How fast does the body respond compared to the mind?"]},eveningIntegration:{type:"reflection",prompt:"Think of your best decisions in life. Did the body know before the mind? Think of your worst. Did the body try to warn you?",deeperPrompt:"The body has been trying to guide you your whole life. You just learned to listen to the mind instead. What if you reversed that?",closingWisdom:"The mind thinks it knows. The body actually knows."},dimension:"body",relatedConcepts:["somatic-intuition","body-wisdom"]},{day:55,phase:"body",title:"Eating with Awareness",subtitle:"You don't eat — you consume unconsciously while your mind is elsewhere",morningTeaching:{type:"practice-intro",concept:"Mindful Eating",keyPoints:["Most meals are consumed on autopilot — screen in hand, mind elsewhere","Eating is one of the most intimate body experiences — yet you barely participate","Taste changes dramatically with full attention — you may discover you don't even like some foods you eat daily","Eating awareness is a microcosm of how you do everything: present or absent"]},dayPractice:{type:"observation",instruction:"Eat ONE meal today with no phone, no screen, no conversation. Full attention on the food: textures, temperatures, flavors, the act of chewing, swallowing, the body receiving nourishment. 20 minutes minimum.",duration:"1 fully conscious meal",checkpoints:["How different was conscious eating from your normal eating?","Did you notice flavors you've never registered before?","When did your mind try to wander? How many times?"]},eveningIntegration:{type:"reflection",prompt:"If you eat unconsciously — what ELSE do you do unconsciously? How much of your life is happening while you're not there?",deeperPrompt:'The Zen masters said: "When eating, just eat." This is the entire teaching condensed. What would change if you applied this to everything?',closingWisdom:"How you eat is how you live. Bring presence to the plate, and it spreads to everything."},dimension:"body",relatedConcepts:["mindful-eating","presence"]},{day:56,phase:"body",title:"Sleep & Dreaming Awareness",subtitle:"You spend a third of your life unconscious — what if you didn't have to?",morningTeaching:{type:"concept",concept:"Sleep Awareness",keyPoints:["The transition between waking and sleep is a doorway most people pass through unconsciously","The hypnagogic state (falling asleep) reveals raw unconscious content","Your quality of sleep reflects your quality of wakefulness","Setting a conscious intention before sleep plants seeds in the unconscious"]},dayPractice:{type:"observation",instruction:"Today, pay attention to your energy levels throughout the day. Notice: when are you most awake? Most drowsy? Does your alertness correlate with mental activity, food, or time? Tonight, try to stay aware as you fall asleep — watch the transition.",duration:"Throughout day + sleep transition",checkpoints:["When were you most alert today?","What is your relationship with sleep?","Can you catch the exact moment consciousness shifts from waking to sleeping?"]},eveningIntegration:{type:"dream-intention",prompt:`Tonight, as you fall asleep, hold one intention: "I want to notice the transition." Don't force anything. Just be curious about the doorway between waking and sleeping.`,deeperPrompt:"Who are you in deep sleep — when there are no thoughts, no emotions, no body sensation, no identity? Something persists. What is it?",closingWisdom:"In deep sleep, the ego dissolves completely — yet you return every morning. You are not the ego."},dimension:"awareness",relatedConcepts:["sleep-awareness","lucidity","consciousness-states"]},{day:57,phase:"body",title:"The Body & Emotions Partnership",subtitle:"Your body and emotions are the same system wearing different names",morningTeaching:{type:"deepening",concept:"Soma-Emotional Unity",keyPoints:["An emotion IS a body event — not a separate phenomenon","Anxiety without a racing heart, tight chest, and shallow breath is just a word","When you resolve the BODY component, the emotional component shifts automatically","This is why talk therapy alone has limits — it addresses the narrative, not the soma"]},dayPractice:{type:"body-scan",instruction:"Today, every emotion you notice — go IMMEDIATELY to the body. Skip the story entirely. What is the body doing? Tightening? Heating? Trembling? Expanding? Stay ONLY with the body sensation for 90 seconds. Watch the emotion transform.",duration:"Every emotional shift",checkpoints:["Did any emotion dissolve through body-only attention?","Is it becoming easier to skip the story and go to the body?","What is the relationship between your body and your most frequent emotion?"]},eveningIntegration:{type:"body-release",prompt:"Right now, do a slow body scan. Where is there still charge from today? Breathe into each area. Give it permission to release without needing to know what it was holding.",deeperPrompt:"If you could heal the body's patterns, the emotions would follow. If you could feel the emotions fully, the body would release. Which direction feels more natural for you?",closingWisdom:"Emotion is the mind's word for what the body already knew."},dimension:"body",relatedConcepts:["soma-emotional","body-emotion-bridge"]},{day:58,phase:"body",title:"Sensory Presence",subtitle:"Your senses are doorways to the present — if you actually use them",morningTeaching:{type:"concept",concept:"Sensory Awareness",keyPoints:["Your five senses only work in the present moment — they cannot sense the past or future","When you are truly seeing, hearing, tasting, touching, smelling — the mind naturally quiets","Most people live through a thin layer of sensory experience while the mind narrates everything","Full sensory engagement is instant meditation"]},dayPractice:{type:"observation",instruction:"Dedicate 5 minutes to each sense today: 5 minutes of pure SEEING (colors, shapes, light), 5 minutes of pure HEARING (layers of sound), 5 minutes of pure TOUCHING (textures, temperatures), 5 minutes of pure SMELLING, 5 minutes of pure TASTING.",duration:"25 minutes total across the day",checkpoints:["Which sense was most vivid when given full attention?","Which sense do you normally ignore most?","Did the mind quiet naturally during pure sensory attention?"]},eveningIntegration:{type:"reflection",prompt:"When you give one sense your FULL attention, everything else falls away — including your problems. What does that tell you about the nature of problems?",deeperPrompt:"Right now, listen to the silence underneath all sounds. Can you hear it? That silence is always here — you just talk over it.",closingWisdom:"The senses are five doors. Any one of them leads to the same room — the present moment."},dimension:"body",relatedConcepts:["sensory-awareness","present-moment"]},{day:59,phase:"body",title:"Posture & Identity",subtitle:"How you hold your body is how you hold your life",morningTeaching:{type:"concept",concept:"Postural Psychology",keyPoints:["Posture is not just physical — it reflects and CREATES your psychological state","Collapsed posture = collapsed energy, low confidence, depression","Rigid posture = rigidity, anxiety, hypervigilance","Aligned and relaxed posture = presence, openness, readiness","Changing posture literally changes your brain chemistry"],scienceNote:"Amy Cuddy's research shows that 2 minutes of expansive posture reduces cortisol by 25% and increases testosterone by 20%. Your body shapes your psychology, not just the reverse."},dayPractice:{type:"body-scan",instruction:"Check your posture 5 times today. Without judging: Where is your chin? Your shoulders? Your chest — open or collapsed? Your pelvis — tilted or neutral? Simply align — head balanced on spine, shoulders relaxed, chest open, belly soft. How does the correction change your mood?",duration:"5 posture check-ins",checkpoints:["What is your default posture?","Did correcting posture change your mood?","What emotional state does your habitual posture create?"]},eveningIntegration:{type:"reflection",prompt:"Your body has been broadcasting your inner state to the world through posture. What has it been saying? What would you like it to say instead?",deeperPrompt:"If your body is the sculpture of your life experiences — what was the sculptor? Fear? Pride? Exhaustion? Protection? Can you see the biography written in your bones?",closingWisdom:"Stand up straight — not with rigidity, but with dignity. Your body knows the difference."},dimension:"body",relatedConcepts:["posture","embodiment","psychosomatic"]},{day:60,phase:"body",title:"The Body Phase Complete",subtitle:"Three lenses calibrated. You now have a complete instrument.",morningTeaching:{type:"review",concept:"Phase 4 Completion",keyPoints:["15 days of body work: somatic intelligence, gut brain, nervous system, intuition, movement, pain, eating, sleep, senses, posture","You now have the complete three-lens system: Head, Heart, Gut","The next phase goes deeper — into the PATTERNS that run beneath all three lenses","Loops and samskaras are the invisible programs that hijack your thoughts, emotions, and body"]},dayPractice:{type:"witness",instruction:"Today, integrate all three lenses into one unified awareness. Head watching thoughts. Heart feeling emotions. Gut sensing the body. All at once, all day. This is the instrument. The next phase shows you what the instrument reveals.",duration:"The entire day",checkpoints:["How long can you sustain triple-lens awareness?","How is your experience of daily life different now vs Day 1?","What is the quality of consciousness when all three lenses are open?"]},eveningIntegration:{type:"integration",prompt:"You are 60 days in. More than halfway. The instrument is built. Now comes the real work — seeing what has been invisible. Patterns, loops, samskaras. Are you ready to see what you've been hiding from yourself?",deeperPrompt:"The three lenses show you what IS. The next phases show you what has been RUNNING you. The difference is liberation.",closingWisdom:"You now have eyes to see. Tomorrow, you turn them toward the invisible chains."},dimension:"awareness",relatedConcepts:["three-lenses-complete","pattern-transition"]}],u=[{day:61,phase:"patterns",title:"What is a Loop?",subtitle:"The invisible programs running your life",morningTeaching:{type:"concept",concept:"Unconscious Loops",keyPoints:["A loop is an automatic behavior pattern: Trigger → Reaction → Temporary Relief → Same Trigger returns",'Patanjali called these "Samskaras" — grooves carved into consciousness by repeated action',"You are not broken — you are programmed. Every loop served a purpose once.","The loop runs in darkness. The moment you SEE it, its power begins to dissolve.",'Krishna in the Bhagavad Gita: "The senses are so strong that they carry away the mind even of a person of discrimination."'],metaphor:`Imagine a vinyl record with a scratch. The needle hits the scratch and repeats the same few seconds of music — forever. Your loops are scratches on the record of your psyche. You've been hearing the same song for years and calling it "my personality."`,scienceNote:'Neuroscience: Repeated neural firing creates myelinated pathways — "neurons that fire together wire together." Loops become neurological highways that the brain defaults to because they require less energy than conscious choice.'},dayPractice:{type:"loop-catch",instruction:"Today, identify ONE loop you run regularly. It could be: reaching for your phone when bored, snapping when criticized, seeking validation after doing something well, or eating when stressed. Write down: (1) The trigger (2) The automatic behavior (3) What temporary relief it provides (4) How long before the trigger returns.",duration:"Throughout the day — catch the loop at least 3 times",checkpoints:["What loop did you identify?","How many times did it run today?","Were you aware DURING the loop or only after?"]},eveningIntegration:{type:"reflection",prompt:'How old is this loop? When did it start? Can you trace it back to the first time it "worked"?',deeperPrompt:`Patanjali's Yoga Sutra 1.2: "Yoga is the cessation of the fluctuations of the mind (Chitta Vritti Nirodha)." Your loops ARE the fluctuations. Seeing them is the beginning of yoga.`,closingWisdom:"You don't break loops. You outgrow them — by seeing them so clearly they can no longer hide."},dimension:"awareness",relatedConcepts:["loops","samskaras","chitta-vritti"]},{day:62,phase:"patterns",title:"Chitta Vritti: The Five Fluctuations",subtitle:"Patanjali mapped your mind 2,500 years ago",morningTeaching:{type:"concept",concept:"Patanjali's Chitta Vritti",keyPoints:["Patanjali identified 5 types of mental fluctuations (Vrittis): Pramana (right knowledge), Viparyaya (misconception), Vikalpa (imagination/fantasy), Nidra (sleep), and Smriti (memory)","EVERY thought you have falls into one of these 5 categories — no exceptions","Most suffering comes from Viparyaya (seeing what isn't there) and Vikalpa (fantasy worlds)","The vrittis are not enemies — they are instruments. The problem is when they control YOU instead of you using THEM.",'Yoga Sutra 1.5-6: "The vrittis are fivefold, painful and painless."'],scienceNote:"Modern cognitive psychology validates Patanjali: cognitive distortions (Beck), system 1 vs system 2 thinking (Kahneman), and memory reconsolidation all map onto the five vrittis with remarkable precision."},dayPractice:{type:"observation",instruction:"For today, categorize EVERY notable thought into Patanjali's 5 categories: (1) Right Knowledge — is this based on direct experience? (2) Misconception — am I seeing what ISN'T there? (3) Fantasy — am I creating imaginary scenarios? (4) Sleep/Dullness — am I checked out? (5) Memory — am I replaying the past? Tally them. Which dominates?",duration:"Throughout the day — minimum 10 categorizations",checkpoints:["Which vritti dominated your mind today?","How much of your thinking was Viparyaya (misconception)?","Could you catch fantasy (Vikalpa) before getting absorbed in it?"]},eveningIntegration:{type:"reflection",prompt:"Look at your vritti tally. What percentage of your mental activity was based on reality (Pramana) vs misconception and fantasy?",deeperPrompt:"Patanjali says freedom comes not from destroying vrittis but from no longer being identified with them. Can you watch a vritti arise without becoming it?",closingWisdom:"The mind has only five moves. Once you see them all, the magician loses power over you."},dimension:"thought",relatedConcepts:["chitta-vritti","patanjali","yoga-sutras"]},{day:63,phase:"patterns",title:"The Three Gunas",subtitle:"Sattva, Rajas, Tamas — the three forces that compose all of existence",morningTeaching:{type:"concept",concept:"The Three Gunas",keyPoints:["Ancient yogic science describes three fundamental forces (Gunas) that compose all matter, mind, and consciousness","TAMAS: inertia, heaviness, darkness, ignorance, depression, laziness, resistance to change","RAJAS: activity, passion, restlessness, desire, ambition, agitation, anxiety","SATTVA: harmony, clarity, lightness, wisdom, peace, balance","Every moment, one guna dominates. Your loops are sustained by Rajas (craving) and Tamas (ignorance). Awareness is Sattva.",'Krishna in Gita 14.5: "Sattva binds by attachment to happiness, Rajas by attachment to action, Tamas by negligence and delusion."'],metaphor:"Think of your inner world as weather. Tamas is fog — you can't see, you don't care, everything feels heavy. Rajas is a storm — intense energy, but destructive and exhausting. Sattva is clear sky — you see everything, the sun shines, but you don't cling to it because you know weather always changes."},dayPractice:{type:"observation",instruction:"Every 2 hours today, check: which guna dominates RIGHT NOW? (1) Tamas: Do I feel heavy, lazy, resistant, numb? (2) Rajas: Do I feel restless, anxious, driven, craving? (3) Sattva: Do I feel clear, peaceful, balanced, aware? Track the shifts. Notice what triggers each state.",duration:"6 guna check-ins throughout the day",checkpoints:["Which guna dominated most of your day?","What foods, activities, or interactions shifted your guna?","Can you feel the transition between gunas as it happens?"]},eveningIntegration:{type:"reflection",prompt:"If you could design tomorrow, which guna would you cultivate? What specific choices would shift you toward Sattva?",deeperPrompt:'The ultimate teaching: even Sattva is a guna — even harmony is a state, not the Self. Beyond all three gunas is pure awareness, the Witness. Krishna: "When the seer knows the gunas as the sole agents, and knows That which is beyond the gunas — he attains My being."',closingWisdom:"You are not the weather. You are the sky in which all weather appears."},dimension:"awareness",relatedConcepts:["gunas","sattva","rajas","tamas","gita"]},{day:64,phase:"patterns",title:"Karma: The Mechanism",subtitle:"Not punishment. Not reward. A mirror.",morningTeaching:{type:"concept",concept:"Karma as Natural Law",keyPoints:["Karma is NOT cosmic reward and punishment. It is the law of cause and effect applied to consciousness.","Every action, thought, and emotion creates an impression (samskara) which creates a tendency (vasana) which creates a loop","There are three types: Sanchita (accumulated), Prarabdha (currently unfolding), and Kriyamana (being created now)","The only karma you can change is Kriyamana — the karma you create in THIS moment through conscious choice",'Krishna: "You have the right to action alone, never to its fruits. Let not the fruits of action be your motive." (Gita 2.47)'],scienceNote:"Epigenetics shows that trauma and behavior patterns can be passed through generations — a biological mechanism for karmic inheritance. Your ancestors' unresolved patterns literally live in your DNA."},dayPractice:{type:"trigger-track",instruction:'Today, for every significant action, ask: "What karma am I creating right now?" Not morally — mechanically. If I react with anger, what impression does that reinforce? If I respond with awareness, what new pattern does that create? Track 5 moments where you consciously chose to create different karma.',duration:"5 conscious karma-creation moments",checkpoints:["How many actions today were reactions (old karma playing out)?","How many were conscious responses (new karma)?","Can you feel the difference between running a pattern and choosing freshly?"]},eveningIntegration:{type:"reflection",prompt:"What karma are you currently living out? Can you identify patterns in your life that repeat across different situations — the same lesson showing up in different clothing?",deeperPrompt:"Karma is not about blame. It is about awareness. The moment you see the pattern, you have the power to respond differently. That is the entire mechanism of liberation.",closingWisdom:"You cannot change what happened. You can only change what you do next. That is the whole of karma yoga."},dimension:"awareness",relatedConcepts:["karma","samskaras","karma-yoga","gita"]},{day:65,phase:"patterns",title:"The Shadow: What You Hide Runs You",subtitle:"Jung meets Yoga — the darkness that is not dark",morningTeaching:{type:"concept",concept:"Shadow Psychology",keyPoints:['Carl Jung: "Until you make the unconscious conscious, it will direct your life and you will call it fate."',"The Shadow is everything you've rejected about yourself — rage, lust, power, vulnerability, selfishness",'Whatever you deny in yourself, you project onto others. "I hate arrogant people" = you have disowned your own assertiveness.',"In yogic terms, the Shadow is Avidya (ignorance) applied to self — refusing to see what is there","Shadow work is not about becoming your shadow. It is about SEEING it, so it stops controlling you from the dark."],metaphor:`Imagine a house where you've locked certain family members in the basement. You pretend they don't exist. But they bang on the floor, shake the walls, and scream at night. Your "personality" is the house. Your Shadow is the basement. Today, you open the door.`,scienceNote:"Research on projection (Baumeister) confirms that qualities people deny in themselves are the ones they most readily attribute to others. Shadow projection is measurable and predictable."},dayPractice:{type:"shadow",instruction:'Today, notice EVERY judgment you make about other people. Write down 5 judgments: "They are so ___." For each one, ask: "Where do I have this quality that I refuse to see?" This is uncomfortable. That discomfort IS the shadow being seen.',duration:"5 projection catches",checkpoints:["What did you judge in others today?","Could you find even a trace of that quality in yourself?","How did it feel to acknowledge the shadow?"]},eveningIntegration:{type:"reflection",prompt:"What quality in others triggers you the most? What would happen if you accepted that quality exists in you too — not as a flaw, but as a disowned strength?",deeperPrompt:"The Shadow contains not only your darkness but your gold — creativity, power, passion that was shamed into hiding. What golden quality did you bury to be acceptable?",closingWisdom:"The cave you fear to enter holds the treasure you seek. — Joseph Campbell"},dimension:"awareness",relatedConcepts:["shadow","projection","jung","avidya"]},{day:66,phase:"patterns",title:"Trigger → Reaction → Consequence",subtitle:"The anatomy of every unconscious pattern dissected",morningTeaching:{type:"concept",concept:"Loop Anatomy",keyPoints:["Every loop follows a precise sequence: CUE → CRAVING → RESPONSE → REWARD","The craving is not for the behavior — it is for the state change. You don't crave food — you crave relief from discomfort.",'Viktor Frankl: "Between stimulus and response there is a space. In that space is our freedom."',"Your entire task is to LENGTHEN that space. One second of gap can save years of suffering.","Patanjali calls this Pratipaksha Bhavana — cultivating the opposite when a destructive pattern arises."],scienceNote:`Charles Duhigg's "habit loop" (cue-routine-reward) maps exactly onto yogic samskara theory. The basal ganglia automates repeated behaviors to save cognitive energy — which means your loops are neurologically efficient prisons.`},dayPractice:{type:"trigger-track",instruction:"Choose your STRONGEST loop (the one from Day 61). Today, dissect it in real-time: (1) What is the exact trigger/cue? (2) What craving arises — what state do you want to escape? (3) What is the automatic response? (4) What reward/relief does it provide? (5) How long before the cycle restarts? Draw this loop on paper.",duration:"Every time the chosen loop activates",checkpoints:["Could you identify the craving beneath the behavior?","What state are you trying to escape when the loop runs?","Did mapping the loop change how it feels to run it?"]},eveningIntegration:{type:"reflection",prompt:"Look at your loop diagram. If you could insert a 3-second pause between the trigger and the reaction — what would you choose instead?",deeperPrompt:"Frankl survived the Holocaust and discovered that even in ultimate suffering, the gap between stimulus and response remains. If he could find it there, you can find it in your daily triggers.",closingWisdom:"Freedom is not the absence of loops. Freedom is the gap within them."},dimension:"awareness",relatedConcepts:["loops","witness-gap","frankl","habit-loop"]},{day:67,phase:"patterns",title:"Validation & Control Loops",subtitle:"The ego's two favorite disguises",morningTeaching:{type:"concept",concept:"Ego Loops",keyPoints:[`VALIDATION LOOPS: "I need to prove I'm worthy." Overwork, people-pleasing, perfectionism — all are validation loops.`,'CONTROL LOOPS: "I must control outcomes to feel safe." Micromanagement, anxiety, manipulation — all are control loops.',"Both stem from the same root: the ego's fundamental insecurity about its own existence.","The Bhagavad Gita's entire teaching to Arjuna is about releasing attachment to outcomes while acting with full commitment.",'Krishna: "Perform your duty equipoised, abandoning all attachment to success or failure." (2.48)']},dayPractice:{type:"loop-catch",instruction:"Today, catch yourself seeking validation or trying to control outcomes. For VALIDATION: notice every time you check for approval, fish for compliments, or adjust behavior to be liked. For CONTROL: notice every time you feel anxious about uncertainty or try to manage someone else's choices. Tally both.",duration:"Throughout the day",checkpoints:["How many validation-seeking moments did you catch?","How many attempts to control what's not controllable?","What would you DO if you didn't need validation or control?"]},eveningIntegration:{type:"reflection",prompt:"Which loop runs stronger in you — validation or control? What childhood experience installed it?",deeperPrompt:"What if your worth is not earned through performance? What if safety comes not from control but from presence? What would that change?",closingWisdom:"The need for approval is the need to exist through others' eyes. You already exist. You don't need permission."},dimension:"awareness",relatedConcepts:["validation-loops","control-loops","ego","gita"]},{day:68,phase:"patterns",title:"Avoidance & Survival Loops",subtitle:"What you refuse to feel runs your life from the shadows",morningTeaching:{type:"concept",concept:"Avoidance Patterns",keyPoints:["AVOIDANCE LOOPS: numbing, distraction, procrastination, substance use, scrolling — all exist to avoid FEELING something.","SURVIVAL LOOPS: fight (aggression), flight (withdrawal), freeze (shutdown), fawn (people-please) — the nervous system's four fear responses.",`Your "personality" is largely your dominant survival strategy. "I'm a people pleaser" = fawn. "I'm independent" = flight.`,"These were brilliant adaptations in childhood. In adulthood, they are prison walls you built yourself.","The body keeps running the survival loop even when the original threat is 20 years gone."],scienceNote:`Peter Levine's Somatic Experiencing shows that trauma creates "incomplete survival responses" — the body literally froze mid-action. Loops are the body trying to complete that action, over and over.`},dayPractice:{type:"loop-catch",instruction:'Today, catch every avoidance behavior: phone checking, snacking when not hungry, zoning out, keeping busy to avoid stillness. For each one, STOP. Ask: "What am I avoiding feeling right now?" Stay with the feeling for 60 seconds. Watch what happens to the avoidance urge.',duration:"Every avoidance behavior",checkpoints:["What did you discover you were avoiding?","What feeling was underneath the avoidance?","What is your dominant survival response: fight, flight, freeze, or fawn?"]},eveningIntegration:{type:"body-release",prompt:"Tonight, instead of any screen or distraction, sit with 5 minutes of silence. No music, no meditation app, no guidance. Just you and whatever arises. Watch what your mind does.",deeperPrompt:"The thing you avoid most persistently is the door you most need to open. What have you been running from? What would happen if you stopped?",closingWisdom:"Avoidance is the most expensive habit you have. Its price is your life, unlived."},dimension:"awareness",relatedConcepts:["avoidance-loops","survival-loops","trauma","somatic"]},{day:69,phase:"patterns",title:"Samskaras: The Ancient Grooves",subtitle:"Your patterns didn't start with you",morningTeaching:{type:"concept",concept:"Samskaras — Deep Conditioning",keyPoints:['Samskara literally means "impression" — like a groove worn into wood by water flowing the same path',"Some samskaras are personal (childhood conditioning). Some are collective (cultural programming). Some, the yogis say, are ancestral.",'Patanjali (Yoga Sutra 4.9): "Samskaras have no beginning in time — because the desire for life is eternal."',"Epigenetics validates this: trauma patterns are literally passed through DNA for at least 3 generations.","Samskaras are not bad. They are the mechanism by which learning is preserved. But unexamined samskaras become prisons.","Dissolution doesn't happen through force but through VIVEKA (discrimination) — seeing clearly what is pattern and what is reality."],metaphor:"A river flowing through rock carves a canyon over millions of years. Your samskaras are canyons carved into consciousness. The water (awareness) can now only flow in these channels. But awareness itself is not the canyon — it is the water."},dayPractice:{type:"journaling",instruction:'Write about your TOP 3 samskaras — patterns so deep they feel like "who I am." For each: (1) Name the pattern. (2) How far back can you trace it? (3) Did a parent or grandparent have this same pattern? (4) If this pattern dissolved tomorrow, who would you be?',duration:"20 minutes journaling",checkpoints:["Which samskara is oldest?","Could you trace any to ancestral patterns?","What would remain if your deepest conditioning dissolved?"]},eveningIntegration:{type:"reflection",prompt:"The yogic teaching: you are not your samskaras. They run THROUGH you, but they are not you. Can you feel the difference between the pattern and the awareness watching the pattern?",deeperPrompt:'If samskaras have "no beginning in time" — who installed them? And who has the power to dissolve them? Only the same awareness that witnessed their creation.',closingWisdom:"You are not the groove. You are the awareness in which grooves form and dissolve."},dimension:"awareness",relatedConcepts:["samskaras","vasanas","epigenetics","patanjali"]},{day:70,phase:"patterns",title:"Relationship Loops",subtitle:"The same dynamic, different faces — the mirror of relationship",morningTeaching:{type:"concept",concept:"Relational Patterns",keyPoints:["You attract the same relationship dynamics repeatedly because relationships are mirrors of your internal patterns","The person who triggers you most is your greatest teacher — they activate your deepest samskaras","Codependency, abandonment fear, intimacy avoidance, power struggles — all are loops, not love","Krishna and Arjuna's relationship in the Gita is the archetype: the Higher Self guiding the confused ego through its patterns",`Neem Karoli Baba: "Don't throw anyone out of your heart." Even the ones who trigger you are serving your growth.`]},dayPractice:{type:"mirror",instruction:"Think of the person who triggers you most. Today, instead of reacting to them, treat every interaction as a MIRROR: What are they showing me about my own unresolved pattern? What button are they pressing — and who installed that button?",duration:"Throughout the day — especially in difficult interactions",checkpoints:["Who triggered you today? What was the mirror showing?","Do you see the same relational dynamic repeating across different relationships?","What would the relationship look like if you responded from awareness instead of your loop?"]},eveningIntegration:{type:"reflection",prompt:"What is your dominant relationship pattern? Pursuer or withdrawer? Caretaker or dependent? Controller or rebel? Where did you learn this dance?",deeperPrompt:'Rumi: "Your task is not to seek for love, but merely to seek and find all the barriers within yourself that you have built against it." What barriers have you built?',closingWisdom:"Every relationship is a mirror. Clean the mirror, and what you see changes."},dimension:"awareness",relatedConcepts:["relationship-loops","projection","mirror","neem-karoli-baba"]},{day:71,phase:"patterns",title:"The Loop You Love",subtitle:"Why you protect the pattern that hurts you most",morningTeaching:{type:"concept",concept:"Secondary Gains",keyPoints:[`Every loop you maintain provides a hidden benefit — a "secondary gain" — that you don't want to give up`,"The victim loop provides attention and sympathy. The busyness loop provides identity. The worry loop provides the illusion of control.","You fight your patterns publicly while secretly feeding them privately",'This is what yogis call "MAYA" — the illusion that is so comfortable you choose it over truth',"Shiva as Nataraja dances on the dwarf of ignorance — YOUR ignorance about your own attachment to suffering."]},dayPractice:{type:"journaling",instruction:'Pick your most persistent loop — the one you keep "trying" to break. Now answer HONESTLY: What does this loop give you? What would you LOSE if it dissolved? Identity? Sympathy? An excuse? A sense of control? Write the uncomfortable truth.',duration:"15 minutes of radical honesty",checkpoints:["What is the secret benefit of your most persistent loop?","Are you actually trying to dissolve it, or just performing the attempt?","What identity would you lose if this pattern dissolved?"]},eveningIntegration:{type:"reflection",prompt:"The hardest truth in consciousness work: you keep what you want to keep. If the pattern is still there, some part of you is choosing it. Can you meet that part with compassion instead of judgment?",deeperPrompt:"Maya is not deception by an external force. Maya is self-deception by choice — because truth would require you to change, and change feels like death to the ego.",closingWisdom:"The chains you love are the hardest to break — because you hold the key and refuse to use it."},dimension:"awareness",relatedConcepts:["secondary-gains","maya","ego-attachment","shiva"]},{day:72,phase:"patterns",title:"Shadow Integration: The Golden Shadow",subtitle:"Your greatness is hiding in the same place as your darkness",morningTeaching:{type:"concept",concept:"Golden Shadow & Integration",keyPoints:["Jung's Golden Shadow: you suppress not only your darkness but also your light — your power, creativity, brilliance",'If you were shamed for being "too much," your aliveness became shadow. If praised only for compliance, your rebellion became shadow.',"Yogic parallel: Brahma (creation) is always active, even when suppressed. Your creative power doesn't die — it festers.",'Shadow integration is not about "fixing" — it is about welcoming ALL parts back into wholeness','Sadhguru: "If you handle your mind properly, every experience can become a stepping stone, not a stumbling block."']},dayPractice:{type:"shadow",instruction:`Today, identify your GOLDEN shadow — the positive qualities you suppress: leadership, creativity, sensuality, power, vulnerability. Ask: "What would I do today if I weren't afraid of being too much?" Do ONE thing that your suppressed brilliance wants to do.`,duration:"One act of golden shadow reclamation",checkpoints:["What positive quality do you suppress?","What did you do today from your golden shadow?","How did it feel to let that quality out?"]},eveningIntegration:{type:"integration",prompt:"The yogis teach that Vishnu preserves what Brahma creates and Shiva destroys. Your shadow work is all three: creating awareness, preserving insight, and destroying illusion. Which phase are you in right now?",deeperPrompt:'When both the dark shadow and the golden shadow are integrated, what remains is not good or bad — it is WHOLE. And wholeness is what the word "yoga" actually means: union.',closingWisdom:"Your shadow doesn't want to be fixed. It wants to be found."},dimension:"awareness",relatedConcepts:["shadow","golden-shadow","jung","trimurti","wholeness"]},{day:73,phase:"patterns",title:"Loop Dissolution: The Witness Method",subtitle:"Not fighting patterns — dissolving them with the light of awareness",morningTeaching:{type:"concept",concept:"Dissolution Through Awareness",keyPoints:["You cannot fight a loop. Fighting IS a loop. Resistance IS the loop recognizing itself and creating more.","The yogic method: SAKSHI BHAVA — the attitude of pure witnessing. Watch the loop without engagement.",'Ramana Maharshi: "The moment you try to stop the mind, you have given it reality. Simply ignore it."',"Neem Karoli Baba dissolved patterns not through analysis but through LOVE — unconditional acceptance of what is.","The loop needs your participation (identification) to survive. When you withdraw identification, it runs once more from momentum, then dies."]},dayPractice:{type:"witness",instruction:'Today, when ANY loop activates (craving, reaction, avoidance), practice the Witness Method: (1) NOTICE: "A loop is running." (2) NAME: "This is the [validation/control/avoidance] loop." (3) NEITHER: neither act on it nor suppress it. (4) WATCH: observe it like weather passing through. Time how long it lasts without your participation.',duration:"Every loop activation",checkpoints:["Could you witness the loop without engaging?","How long did the loop run when you didn't feed it?","What happened in your body when you refused to participate in the loop?"]},eveningIntegration:{type:"reflection",prompt:"Dissolution is not dramatic. It is quiet. A loop simply stops being interesting when you see it completely. Did any loop lose some of its charge today?",deeperPrompt:'Neem Karoli Baba was asked how to dissolve anger. He said: "Love everyone, serve everyone, remember God." The simplest teachings dissolve the most complex patterns.',closingWisdom:"You don't destroy the darkness. You turn on the light. The darkness was never real."},dimension:"awareness",relatedConcepts:["sakshi-bhava","witness","loop-dissolution","ramana","neem-karoli-baba"]},{day:74,phase:"patterns",title:"From Loop to Choice",subtitle:"The moment reaction becomes response — this is liberation",morningTeaching:{type:"concept",concept:"Conscious Choice",keyPoints:[`Viktor Frankl survived Auschwitz and discovered: "The last of the human freedoms — to choose one's attitude in any given set of circumstances."`,"A loop is reaction. A response is choice. The difference is ONE SECOND of awareness.","Patanjali's Pratipaksha Bhavana (Yoga Sutra 2.33): When disturbed by negative thoughts, cultivate the opposite.","This is not positive thinking. It is conscious CHOOSING — from awareness, not from suppression.",'Krishna to Arjuna: "Arise! Stand up and fight!" — not fighting others, but fighting unconsciousness itself.'],scienceNote:"Neuroplasticity research confirms: every time you choose a new response instead of the old reaction, you literally rewire the brain. The old pathway weakens and the new one strengthens. Freedom is neurological."},dayPractice:{type:"trigger-track",instruction:"Today, attempt CONSCIOUS PATTERN INTERRUPTION. Choose one loop. When it triggers: (1) Feel the pull. (2) Take 3 breaths. (3) Choose a DIFFERENT response — any response that is not the automatic one. Walk instead of scroll. Breathe instead of snap. Sit instead of avoid. One conscious choice, repeated.",duration:"Every time the chosen loop triggers",checkpoints:["How many times could you successfully interrupt the pattern?","What new response did you choose?","How did it feel to respond instead of react?"]},eveningIntegration:{type:"reflection",prompt:"Frankl's gap is real. You felt it today. Every time you paused between trigger and response, you were FREE — even if only for a second. How does freedom feel?",deeperPrompt:"If you could respond with awareness to EVERY trigger for one full day — who would you be? That person is not a goal. That person is who you already are, underneath the loops.",closingWisdom:"You don't become free. You discover you always were. The loops were never you."},dimension:"awareness",relatedConcepts:["frankl","conscious-choice","pratipaksha-bhavana","neuroplasticity"]},{day:75,phase:"patterns",title:"Patterns Phase Complete",subtitle:"You see the machinery — now you question the operator",morningTeaching:{type:"review",concept:"Phase 5 Integration",keyPoints:["In 15 days you have mapped your inner machinery: Chitta Vritti, Gunas, Karma, Shadow, Samskaras, Loops","You now carry Patanjali's framework (vrittis, samskaras), Krishna's teaching (gunas, karma), Jung's shadow work, and Frankl's gap","You can identify your patterns, name them, trace their origins, and begin dissolving them through witnessing","The next phase asks the ultimate question: if I am not my patterns, my thoughts, my emotions, or my body — WHO AM I?","This question is the bridge between psychology and liberation."]},dayPractice:{type:"journaling",instruction:`Write a "Loop Inventory." List every loop you've identified in 15 days. For each: name it, rate its strength (1-10), note if it weakened during this phase, and write one sentence about what it's protecting. This is your pattern map — your personal machine blueprint.`,duration:"20 minutes",checkpoints:["How many loops did you identify?","Which loop weakened most during this phase?","If all your loops dissolved, what would remain?"]},eveningIntegration:{type:"integration",prompt:"You now see the machinery. But seeing the machinery raises a question: WHO is seeing it? The machine cannot see itself. Something beyond the machine is looking. What is that?",deeperPrompt:`Ramana Maharshi: "The question 'Who am I?' is not really meant to get an answer. The question is meant to dissolve the questioner." The next 15 days take you there.`,closingWisdom:"You've seen the prison. Now you meet the one who was never in it."},dimension:"awareness",relatedConcepts:["integration","who-am-i","ramana"]}],d=[{day:76,phase:"inquiry",title:"Who Am I?",subtitle:"The question that ends all questions",morningTeaching:{type:"concept",concept:"Ramana Maharshi's Self-Inquiry",keyPoints:['Ramana Maharshi, at age 16, had a spontaneous death experience. He asked: "Who dies?" and found what cannot die.','His entire teaching is one question: "Who am I?" — not as philosophy, but as DIRECT INVESTIGATION.','The method: whenever a thought arises, ask "To whom does this thought arise?" → "To me." → "Who am I?"',"The question is not meant to produce an intellectual answer. It is meant to trace attention back to its SOURCE.","What you find is not a new identity. It is the absence of all identity — pure awareness, the Self."],metaphor:"A man searches the whole world for a treasure, visiting every country, scaling every mountain. Exhausted, he returns home — and finds the treasure was buried under his own house. The search was necessary to exhaust all other possibilities. Now you search the only place left: within."},dayPractice:{type:"self-inquiry",instruction:'Sit for 15 minutes. Close your eyes. Watch thoughts arise. For EACH thought, ask: "To whom does this thought arise?" The answer is always "to me." Then ask: "Who am I?" Do NOT answer with concepts ("I am consciousness," "I am awareness"). Instead, LOOK for the "I." Try to find where the sense of "I" originates. Stay with the looking, not the answering.',duration:"15 minutes formal + inquiry throughout the day",checkpoints:['Could you trace the "I" back toward its source?',"What happens when you look for the looker?","Did the mind try to answer with concepts? Could you go beyond the concepts?"]},eveningIntegration:{type:"neti-neti",prompt:'When you asked "Who am I?" — what did you find? Not as a thought, but as an experience. What is the felt sense of pure "I" before any content is added?',deeperPrompt:'Ramana: "The Self is not something new to be acquired. It is always there. All that is needed is to get rid of the false notion that it is not realized." What if you are already what you seek?',closingWisdom:'The answer to "Who am I?" is not a word. It is the silence that remains when all words stop.'},dimension:"awareness",relatedConcepts:["self-inquiry","ramana","atma-vichara"]},{day:77,phase:"inquiry",title:"The I-Thought",subtitle:"The root of all other thoughts",morningTeaching:{type:"deepening",concept:"The Root Thought",keyPoints:['Ramana taught that the "I-thought" (Aham Vritti) is the root of ALL other thoughts.','"I am hungry" — remove the I and there is just hunger. "I am afraid" — remove the I and there is just fear.',`The I-thought is not the Self. It is the ego's first movement — the identification "I am this body-mind."`,"Every other thought hangs from this root thought like branches from a tree trunk.","Cut the root, and the entire tree falls. This is self-inquiry — finding and dissolving the I-thought at its source."],scienceNote:'Neuroscience: The "default mode network" (DMN) creates the narrative self — the continuous "I, me, mine" story. Meditation reduces DMN activity. Self-inquiry targets it directly.'},dayPractice:{type:"self-inquiry",instruction:'Today, practice tracing every thought back to "I": "I need to finish work" → who needs? "I am worried" → who is worried? "I should meditate better" → who should? Keep pulling the thread of "I" until you arrive at the bare sense of existence — "I am" without any predicate. Rest there.',duration:"15 minutes formal inquiry + daily awareness",checkpoints:[`Could you find a thought that doesn't have "I" attached to it?`,'What remains when you strip "I am ___" down to just "I am"?','What is the felt sense of "I" before it attaches to anything?']},eveningIntegration:{type:"reflection",prompt:'The "I" that woke up this morning — is it the same "I" that is reflecting now? The body changed, thoughts changed, emotions changed. What remained constant?',deeperPrompt:`Nisargadatta Maharaj: "The sense 'I am' is the beginning of all experience. Before 'I am,' there is only the Absolute." Can you sense the "I am" before it becomes "I am [something]"?`,closingWisdom:"I am. Just that. Before the body, before the name, before the story. I am."},dimension:"awareness",relatedConcepts:["i-thought","aham-vritti","nisargadatta","dmn"]},{day:78,phase:"inquiry",title:"Neti Neti: Not This, Not This",subtitle:"Stripping away everything you are not",morningTeaching:{type:"concept",concept:"Neti Neti — The Method of Negation",keyPoints:["Neti Neti comes from the Brihadaranyaka Upanishad — one of the oldest spiritual methods in human history.",'The method: systematically negate everything you can perceive. "I am not this body" (because I can observe it). "I am not these thoughts" (because I can watch them).',"Whatever can be observed CANNOT be the observer. The eye cannot see itself.","After negating everything — body, mind, emotions, identity, memory — what remains cannot be negated. THAT is the Self.","Adi Shankara formalized this into Advaita Vedanta: there is only ONE reality, appearing as many. You are THAT."],metaphor:"Imagine you are wearing 100 costumes, one over another. Each costume is an identity: your job, your name, your beliefs, your memories. Neti Neti removes them one by one. When the last costume falls — you are not naked. You discover you were never the costumes. You are the space that wore them."},dayPractice:{type:"neti-neti",instruction:'Sit for 15 minutes. Systematically inquire: "Am I this body?" → I can feel it, so I am aware OF it. Not this. "Am I these thoughts?" → I can watch them. Not this. "Am I these emotions?" → They come and go, I remain. Not this. "Am I my memories?" → They change, I persist. Not this. "Am I my identity?" → It shifts with context. Not this. What remains? REST in what remains.',duration:"15 minutes formal + awareness throughout the day",checkpoints:['Could you genuinely feel "I am not my body" — not just think it?',"What resisted being negated most?","What is left when everything is negated?"]},eveningIntegration:{type:"neti-neti",prompt:"Of everything you negated today, what did the ego cling to most tightly? That is your primary identification — the last veil.",deeperPrompt:'Shankara: "Brahman is the only truth. The world is illusory. The individual self is none other than Brahman." Not as belief — as investigation. Can you verify this through direct experience?',closingWisdom:"What remains when you remove everything that changes is the only thing that is real."},dimension:"awareness",relatedConcepts:["neti-neti","shankara","advaita","upanishads"]},{day:79,phase:"inquiry",title:"Beyond the Body",subtitle:"I have a body — but am I the body?",morningTeaching:{type:"deepening",concept:"Dis-identification from the Physical",keyPoints:["Every cell in your body replaces itself over ~7-10 years. Your body today is literally not the same body from childhood.","In deep sleep, you have no awareness of the body — yet YOU persist. Something survives the body's absence.","The body is an instrument — extraordinary, intelligent, sacred — but it is not what YOU are.","This is NOT body-rejection (that is spiritual bypassing). It is body-appreciation without body-identification.",'Vivekananda: "The body is the name of a series of changes. The child body, the young body, the old body are three different bodies. The soul remains the same."']},dayPractice:{type:"witness",instruction:'Today, observe your body AS an object of awareness, not AS you. Feel your hands — but notice that YOU are the one feeling. Walk — but notice that YOU are the one aware of walking. Can you find the border between "body" and "the awareness of body"?',duration:"Throughout the day",checkpoints:["Can you sense yourself as separate from the body?","Not separate as in disconnected — separate as in larger than the body?","What knows that the body is here?"]},eveningIntegration:{type:"reflection",prompt:`In deep sleep tonight, your body will be there but "you" won't know it. Who are you in deep sleep?`,deeperPrompt:'If you lost an arm, would you be less "you"? If you changed your face, would the watcher behind the eyes change?',closingWisdom:"You don't have a soul. You are a soul. You have a body."},dimension:"awareness",relatedConcepts:["dis-identification","body","vivekananda"]},{day:80,phase:"inquiry",title:"The Five Koshas: Sheaths of Being",subtitle:"Five layers between you and You",morningTeaching:{type:"concept",concept:"Pancha Kosha — The Five Sheaths",keyPoints:["The Taittiriya Upanishad describes 5 sheaths (Koshas) that cover the Self like layers of an onion:","1. ANNAMAYA KOSHA — Food body (physical form, bones, organs)","2. PRANAMAYA KOSHA — Energy body (breath, prana, life force)","3. MANOMAYA KOSHA — Mental body (thoughts, emotions, the lower mind)","4. VIJNANAMAYA KOSHA — Wisdom body (discrimination, insight, higher intellect)","5. ANANDAMAYA KOSHA — Bliss body (deep joy, the thinnest veil before pure Self)","Beyond all 5 koshas is ATMAN — the Self, which is identical to BRAHMAN, the universal consciousness."],metaphor:"Imagine a lamp with five lampshades. The light (Atman) is always shining, but each shade filters and colors the light differently. The food body creates the densest filter. The bliss body is the finest veil — almost transparent. Self-inquiry removes the shades to see the pure light."},dayPractice:{type:"observation",instruction:"Today, observe which kosha you are operating from in each moment: Are you in Annamaya (hungry, tired, physical focus)? Pranamaya (energized, breathing, vitality)? Manomaya (thinking, emoting, planning)? Vijnanamaya (discerning, understanding, insightful)? Anandamaya (deep peace, gratitude, joy beyond reason)? Track your kosha shifts through the day.",duration:"Throughout the day — map 6+ transitions",checkpoints:["Which kosha do you live in most?","Can you shift between koshas consciously?","Have you ever touched Anandamaya — joy without cause?"]},eveningIntegration:{type:"reflection",prompt:"If you peel back all 5 koshas through awareness — physical, energy, mental, wisdom, bliss — what is left? The Upanishad says: THAT is what you are.",deeperPrompt:"The koshas are not obstacles — they are instruments. Each one is a gift. But identifying WITH any of them is like mistaking the lampshade for the light.",closingWisdom:"You are not the food body, not the breath, not the mind, not even bliss. You are the light that illuminates all five."},dimension:"awareness",relatedConcepts:["koshas","pancha-kosha","upanishads","atman"]},{day:81,phase:"inquiry",title:"Beyond the Mind",subtitle:"I have thoughts — but am I the thinker?",morningTeaching:{type:"deepening",concept:"Dis-identification from Mind",keyPoints:['Descartes said "I think, therefore I am." Ramana said: "I am, therefore thoughts appear."',"Thoughts arise and dissolve. In deep sleep, there are no thoughts — but you exist. Existence precedes thought.","The mind is a magnificent instrument — but you are not the instrument. You are the one using it.",'Nisargadatta: "I am not my thoughts. I am the one who watches the thoughts."',"The greatest tragedy of human life is identifying with the mind's content instead of the awareness that contains it."]},dayPractice:{type:"self-inquiry",instruction:'Today, treat every thought as a visitor to an empty room. You are the room. Thoughts enter and leave, but the room (you) never changes. When a thought arises, greet it: "Welcome, thought." When it leaves: "Goodbye, thought." You remain. The room remains.',duration:"15 minutes formal + daily practice",checkpoints:['Could you experience yourself as the "room" rather than the thoughts?',"What happens in the moment between two thoughts?","Is the space between thoughts the same as the space during thoughts?"]},eveningIntegration:{type:"neti-neti",prompt:"If you are not the thinker, then who has been running your life? And who just realized that?",deeperPrompt:'Vivekananda: "Take up one idea. Make that one idea your life. Think of it, dream of it, live on that idea. Let the brain, muscles, nerves, every part of your body, be full of that idea." Your idea for now: I am not the mind.',closingWisdom:"The mind is a wonderful servant but a terrible master. You've been serving it. Time to reclaim the throne."},dimension:"awareness",relatedConcepts:["dis-identification","mind","nisargadatta","vivekananda"]},{day:82,phase:"inquiry",title:"Beyond Emotions & Roles",subtitle:"Stripping every mask to find the face beneath",morningTeaching:{type:"deepening",concept:"Identity Dissolution",keyPoints:["You are not your emotions — they change every hour but YOU persist. Anger visits, joy visits, sadness visits. You are the host.","You are not your roles — father, daughter, worker, friend. Remove every role and something remains that was never a role.","You are not your name — a sound given to you by someone else. Before the name, you existed.","You are not your story — the narrative keeps changing (childhood felt different from how you see it now).","What are you when you remove body, mind, emotions, roles, name, and story? THAT is the inquiry."]},dayPractice:{type:"neti-neti",instruction:'Today, practice "costume removal." In every interaction, notice which ROLE you are playing: professional you, parent you, friend you, spiritual you. After each interaction, internally remove that costume: "That was a role. I am not the role." Who remains when no costume is on?',duration:"In every interaction today",checkpoints:["How many different roles did you play today?",'Which role feels most "real" — which one do you most identify with?',"Who is the one switching between roles?"]},eveningIntegration:{type:"neti-neti",prompt:"If you are not the body, not the mind, not the emotions, not any role — and yet you EXIST — what are you?",deeperPrompt:`Shankara's Atma Shatakam: "I am not the mind, intellect, ego, or memory. Not the ear, tongue, nose, or eyes. Not ether, earth, fire, or air. I am pure consciousness and bliss. I am Shiva. I am Shiva."`,closingWisdom:"Strip everything away. What you cannot remove is what you are."},dimension:"awareness",relatedConcepts:["identity","roles","atma-shatakam","shankara"]},{day:83,phase:"inquiry",title:"The Witness Deepens",subtitle:"Who is watching the watcher?",morningTeaching:{type:"deepening",concept:"The Ultimate Witness",keyPoints:["You learned to witness thoughts. Then emotions. Then the body. But now — who is witnessing the witness?","This question collapses the observer-observed split. The witness cannot be witnessed because it IS witnessing itself.",'Ramana: "There are no two selves — one to know the other. The Self is self-luminous."',"This is not intellectual. It is experiential. The eye trying to see itself. Awareness aware of itself.","When seeking stops because the seeker dissolves — THAT is recognition."]},dayPractice:{type:"witness",instruction:'Today, sit for 15 minutes and try to witness the witness. Watch thoughts — then turn attention to the one watching. You will find... nothing objectifiable. Rest there. That "nothing" is not empty — it is full awareness, unable to be seen because it IS the seeing.',duration:"15 minutes formal + contemplation throughout",checkpoints:["What happened when you tried to witness the witness?",`Did the mind create a "higher witness" to observe from? (That's just another thought!)`,"Can you rest in the impossibility of seeing the seer?"]},eveningIntegration:{type:"reflection",prompt:"The eye cannot see itself. Awareness cannot be made into an object of awareness. Does that frustrate you or liberate you?",deeperPrompt:'Nisargadatta: "You are the space in which everything happens. You are the awareness. You are not what happens — you are the happening itself."',closingWisdom:"You cannot find yourself because you are the one doing the finding. Stop seeking and you are found."},dimension:"awareness",relatedConcepts:["witness-depth","self-luminous","ramana","nisargadatta"]},{day:84,phase:"inquiry",title:"Silence as Answer",subtitle:"When the mind stops asking — what remains?",morningTeaching:{type:"concept",concept:"The Power of Silence",keyPoints:["Ramana Maharshi's highest teaching was SILENCE. He would often sit without speaking, and seekers would have their questions dissolved by his presence alone.","Silence is not the absence of sound. It is the absence of the mind's commentary.","In that silence, there is a fullness — not emptiness. It is consciousness resting in itself.",`Dakshinamurthy (Shiva as the silent teacher): "The teacher is young, the disciples are old. The teacher's teaching is silence, and the disciples' doubts are dispelled."`,"The greatest truths cannot be spoken. They can only be pointed at. Silence IS the pointing."]},dayPractice:{type:"silence",instruction:"Practice 30 minutes of intentional silence today. Not just outer silence — inner silence. Don't speak externally. Don't speak internally. When the mind comments, let it go. Rest in the space before and after each thought. Find the silence that is always there under the noise.",duration:"30 minutes of deep silence",checkpoints:["Could you find inner silence even briefly?",'What was silence like when you stopped calling it "empty"?',"Did any insight arise FROM silence rather than from thought?"]},eveningIntegration:{type:"reflection",prompt:"What did silence reveal that thinking could not?",deeperPrompt:'Rumi: "Silence is the language of God. All else is poor translation." What was God (consciousness, truth, reality) saying in the silence today?',closingWisdom:"When the question dissolves, the answer was never needed. What remains is what you always were."},dimension:"awareness",relatedConcepts:["silence","ramana","dakshinamurthy","mauna"]},{day:85,phase:"inquiry",title:"The Fear of Disappearing",subtitle:"Ego death — the mind's ultimate fear",morningTeaching:{type:"concept",concept:"Ego Dissolution Fear",keyPoints:["As self-inquiry deepens, the ego feels threatened. It equates dissolving identity with DYING.",'Symptoms: panic, resistance, boredom, "this is pointless," anger at the practice, existential anxiety',"THIS FEAR IS THE BEST SIGN. It means the inquiry is working — it is reaching the ego's core.",'Ramana experienced literal "death" at 16. He let it happen. What survived the death of the ego was the Self — deathless, eternal.',"You are not being asked to die. You are being asked to discover what in you has never been born and therefore cannot die."],scienceNote:`fMRI studies of deep meditators show decreased activity in the posterior cingulate cortex — the brain's "self-referential" center. The brain literally lets go of "me." Those meditators report not loss but liberation.`},dayPractice:{type:"self-inquiry",instruction:`Today, face the fear directly. Sit for 15 minutes and ask: "If I (the ego, the identity) completely dissolved right now — what would happen? Who would be left?" Let the fear arise. Don't push it away. Sit WITH the terror. Breathe. Discover: even in the presence of the fear of dissolution — YOU are still here, aware.`,duration:"15 minutes + observation of ego resistance throughout the day",checkpoints:["Did fear arise during the inquiry?","Could you sit with the fear without fleeing?","In the midst of the fear — was something still aware? Something untouched by the fear?"]},eveningIntegration:{type:"reflection",prompt:"The ego fears disappearing. But has the ego ever actually been REAL? Can you find the ego as a fixed entity, or is it just a stream of thoughts claiming to be a person?",deeperPrompt:'What Ramana discovered: the ego was never born. It was a misidentification — consciousness identifying with body-mind. "Death" of the ego is not death at all. It is waking up from a dream.',closingWisdom:"You are not dying. You are waking up. What dies is only what was never real."},dimension:"awareness",relatedConcepts:["ego-death","dissolution","ramana","deathless"]},{day:86,phase:"inquiry",title:"Being vs. Becoming",subtitle:"You are already what you seek",morningTeaching:{type:"concept",concept:"Pure Being",keyPoints:["The entire spiritual search is a paradox: you are searching for what you already are.",`The mind says: "I must BECOME enlightened." Truth says: "You are already THAT — you just don't see it."`,"Seeking itself creates distance. The act of searching implies the object is elsewhere.",'Nisargadatta: "You are already that which you are seeking. The search is what covers it up."',"Sat-Chit-Ananda (Being-Consciousness-Bliss) is not a state to achieve. It is your nature, RIGHT NOW, obscured only by identification with body-mind."]},dayPractice:{type:"witness",instruction:`Today, stop seeking. Instead, REST in what is already here. Not trying to be more aware, more present, more conscious. Just BE. When the mind says "I should be more..." reply: "I already am." When it says "I'm not there yet..." reply: "There is no 'there.' Here is all there is."`,duration:"Entire day — stop seeking, start being",checkpoints:["Could you rest in being without trying to become anything?",'How does the mind react to "no more seeking"?',"What is the quality of experience when you stop trying to improve it?"]},eveningIntegration:{type:"surrender",prompt:"What if the entire journey of 118 days is not about GETTING somewhere but about removing what covers where you already are?",deeperPrompt:'Ramana: "Realization is not to be attained. It is already there. All that is needed is to remove the veil." What is your veil? And who is beneath it?',closingWisdom:"You are not on a journey to somewhere. You are on a journey to here."},dimension:"awareness",relatedConcepts:["being","sat-chit-ananda","nisargadatta","realization"]},{day:87,phase:"inquiry",title:"Vivekananda's Practical Vedanta",subtitle:"The fire of knowledge must burn in life, not in books",morningTeaching:{type:"concept",concept:"Vedanta in Action",keyPoints:['Swami Vivekananda brought Vedanta out of the caves and into the streets. His teaching: "Arise, awake, and stop not till the goal is reached!"',"Practical Vedanta means: your realization must express in HOW YOU LIVE, not just what you experience in meditation.",'Vivekananda: "Each soul is potentially divine. The goal is to manifest this divinity within."','He unified all four yoga paths: "Jnana is the yoga for the thinker, Bhakti for the feeler, Karma for the doer, Raja for the mystic."','Your self-inquiry must NOT create a spiritual ego that "knows the truth" but lives no differently. Knowledge without transformation is entertainment.']},dayPractice:{type:"observation",instruction:'Today, bring self-inquiry into ACTIVE LIFE. At work, in relationships, while commuting — maintain the question "Who am I?" as a background hum. Not withdrawing from life but engaging MORE fully while being aware of the awareness behind it all.',duration:"Entire day — inquiry in the marketplace",checkpoints:["Could you maintain inquiry awareness during active tasks?","Did inquiry change the QUALITY of your engagement with life?","Is there a difference between meditation awareness and marketplace awareness?"]},eveningIntegration:{type:"reflection",prompt:'Vivekananda said: "The greatest religion is to be true to your own nature." What IS your true nature — not the conditioned personality, but the natural expression of your consciousness?',deeperPrompt:"If every soul is divine, then the person who annoyed you today is also divine. Can you see through their conditioning to the same awareness that looks through your eyes?",closingWisdom:"Enlightenment is not escape from life. It is seeing life as it truly is — sacred, whole, and already perfect."},dimension:"awareness",relatedConcepts:["vivekananda","practical-vedanta","divinity","engagement"]},{day:88,phase:"inquiry",title:"The V-Levels: Your Growth Map",subtitle:"Understanding the terrain of consciousness evolution",morningTeaching:{type:"concept",concept:"Vertical Levels of Consciousness",keyPoints:["Consciousness evolves through recognizable stages — not as achievement, but as deepening.","Band 0 (Sleeper): Life on autopilot. No awareness of patterns. Band 1 (Questioner): Something feels off. Seeking begins.","Band 2 (Observer): The witness is born. You can watch your thoughts. Band 3 (Alchemist): Patterns become teachers.","Band 4 (Navigator): The gap between trigger and response opens. Band 5 (Architect): Life built from inside out.",'Band 6 (Channel): Ego softens. Intuition leads. Band 7 (Source): "I am what I was seeking." Search ends.',"You are somewhere on this map. Not as judgment — as orientation. Where you are is perfect. Where you're going is irrelevant — only this step matters."]},dayPractice:{type:"journaling",instruction:'Reflect honestly: which V-Level band do you live in MOST of the time? (Not your peak moments — your baseline.) Write about: (1) Your dominant state. (2) What triggers you back to lower bands. (3) What naturally lifts you to higher states. (4) What feels like your "next step" — not a year from now, but today.',duration:"15 minutes of honest self-assessment",checkpoints:["Where is your honest baseline?","What is your edge — the next band you touch sometimes but can't sustain?","What would stabilizing one band higher change in your daily life?"]},eveningIntegration:{type:"reflection",prompt:`The V-Levels are not a ladder to climb. They are depths to discover. You don't "achieve" Band 7 — you realize it was always the ground you were standing on.`,deeperPrompt:"Nisargadatta lived at Band 7 while running a tobacco shop. Ramana lived at Band 7 while sitting on a couch. The band is not about what you DO — it is about who you ARE while doing it.",closingWisdom:"You are already the highest level. You are just remembering it layer by layer."},dimension:"awareness",relatedConcepts:["v-levels","consciousness-bands","growth-map","baseline"]},{day:89,phase:"inquiry",title:"Self-Inquiry in Daily Life",subtitle:"Taking the question into the marketplace",morningTeaching:{type:"practice-intro",concept:"Living Self-Inquiry",keyPoints:["The real test of inquiry is not what happens on the cushion but what happens in traffic, in arguments, in boredom.",'Sadhguru: "Spirituality is not about looking up or looking down. It is about looking inward."',"Every moment of daily life is an opportunity for inquiry: Who is eating? Who is driving? Who is angry?",`The question "Who am I?" doesn't need formal practice. It becomes a lens through which you see EVERYTHING.`,"When inquiry becomes continuous, you don't meditate anymore. Your entire life IS the meditation."]},dayPractice:{type:"self-inquiry",instruction:`Today, carry the question "Who am I?" into EVERY activity. Eating: who is tasting? Working: who is thinking? In conversation: who is listening? In frustration: who is frustrated? Don't answer. Just let the question illuminate the moment. Count how many times you remember to ask.`,duration:"The entire day — minimum 20 inquiry moments",checkpoints:['How many times did you remember to ask "Who am I?" today?',"What changed in the quality of experience when the question was present?","Did the question feel different in action vs in stillness?"]},eveningIntegration:{type:"reflection",prompt:"When inquiry was present during your day — was there a different quality to experience? More spacious? More alive? More real?",deeperPrompt:'The inquiry is not separate from life. Life IS the inquiry. Every moment, existence is asking you: "Who are you?" Every moment, your response IS your answer.',closingWisdom:"The market, the kitchen, the office — these are your temples now. The question is your prayer."},dimension:"awareness",relatedConcepts:["daily-inquiry","sadhguru","living-meditation"]},{day:90,phase:"inquiry",title:"Inquiry Phase Complete",subtitle:"The question dissolved — presence remains",morningTeaching:{type:"review",concept:"Phase 6 Integration",keyPoints:["In 15 days, you have practiced humanity's most powerful tools of self-knowledge: Ramana's self-inquiry, Shankara's neti neti, the kosha map, Vivekananda's practical vedanta.","You have faced the ego's fear of dissolution and discovered that what you are cannot die because it was never born.","You have learned the V-Level map — not as achievement but as orientation.","The next phase moves from subtraction (removing what you're not) to sensing what you ARE: the energy body, the chakra system, prana, kundalini.","Self-inquiry doesn't end. It becomes your constant companion — the silent question that illuminates everything."]},dayPractice:{type:"journaling",instruction:'Write: "Before self-inquiry, I was... During self-inquiry, I discovered... After self-inquiry, I am..." Let the words come from the deepest place you can access. Not performance — truth.',duration:"15 minutes",checkpoints:["What was the most profound moment of this phase?","Has your sense of identity shifted?",'Can you hold the question "Who am I?" lightly, like a companion rather than a task?']},eveningIntegration:{type:"integration",prompt:'Ramana was once asked: "What is the highest truth?" He answered: "BE." Not know. Not understand. Not believe. Just BE.',deeperPrompt:`You've asked "Who am I?" for 15 days. The mind may still not have an answer. But something in you KNOWS — without words, without concepts. Can you feel it?`,closingWisdom:"The answer was never a word. It was always this — this awareness, reading these words, right now. You found it. You were it all along."},dimension:"awareness",relatedConcepts:["integration","self-inquiry","being","ramana"]}],c=[{day:91,phase:"energy",title:"The Energy Body",subtitle:"Beyond the physical — sensing what you cannot see",morningTeaching:{type:"concept",concept:"The Subtle Body (Sukshma Sharira)",keyPoints:["You have three bodies: Sthula (physical), Sukshma (subtle/energy), and Karana (causal). You've been living in only one.","The subtle body contains 72,000 nadis (energy channels), 7 major chakras, and prana (life force).","This is not metaphor. You can FEEL the energy body — tingling in meditation, goosebumps from truth, heat in the hands.",'Yogananda: "The body is an instrument of energy. When the energy withdraws, the body falls. You are the energy, not the instrument."',"Science is catching up: bioelectromagnetic fields, heart coherence, and fascia conductivity all point to an energy system beyond the physical."],scienceNote:"The heart generates an electromagnetic field that can be measured several feet from the body (HeartMath Institute). Acupuncture points correspond to areas of lower electrical resistance. The energy body has measurable correlates."},dayPractice:{type:"chakra-sense",instruction:"Rub your palms together vigorously for 30 seconds. Then slowly separate them to about 6 inches apart. Move them closer and farther. Can you feel resistance — like compressing an invisible ball? That is prana between your hands. Practice this 3 times today and notice the energy growing stronger.",duration:"3 energy-sensing sessions",checkpoints:["Could you feel the energy between your hands?","Did the sensation grow stronger with practice?","Can you feel energy in other parts of the body when you bring attention there?"]},eveningIntegration:{type:"reflection",prompt:"The physical body is visible. The energy body is felt. The causal body is the blueprint. Tonight, as you lie down, scan not for muscle tension but for ENERGY — tingling, warmth, flow, or blockage.",deeperPrompt:"What if disease, depression, and disconnection are first energy disturbances — before they become physical? What if healing happens in the subtle body first?",closingWisdom:"You are not a body generating energy. You are energy condensed into a body."},dimension:"body",relatedConcepts:["energy-body","prana","sukshma-sharira"]},{day:92,phase:"energy",title:"Pranayama: The Science of Breath",subtitle:"Prana is not just breath — it is the bridge between body and consciousness",morningTeaching:{type:"concept",concept:"Pranayama — Beyond Breathing Exercises",keyPoints:['Prana literally means "first unit of energy." It is the life force that animates all of existence.',"Pranayama is not breathing exercises. It is PRANA-YAMA: expansion (or control) of the life force.","Patanjali lists pranayama as the 4th limb of yoga — the bridge between external practices (body) and internal practices (mind).","There are 5 pranas: Prana (inward), Apana (downward), Samana (digestive), Udana (upward/speech), Vyana (circulation)",'Sadhguru: "If you gain mastery over the five pranas, there is nothing in this universe that is beyond your reach."',"Today you learn conscious breath — not to control, but to sensitize yourself to the life force moving through you."],scienceNote:"Controlled breathing activates the vagus nerve, shifting the autonomic nervous system from sympathetic (stress) to parasympathetic (healing). Slow breathing increases heart rate variability — a marker of emotional resilience and longevity."},dayPractice:{type:"breath-watch",instruction:"Practice three levels of breath awareness today: (1) GROSS: 5 minutes watching physical breath — in/out, belly/chest. (2) SUBTLE: 5 minutes sensing prana — can you feel energy moving with the breath? Tingling? Warmth? (3) SUBTLEST: 5 minutes watching the PAUSE between breaths. In that pause — prana is still. What is that stillness?",duration:"3 × 5-minute sessions",checkpoints:["Could you feel prana (not just air) moving?","What happened in the pause between breaths?","Did your state change after the practice?"]},eveningIntegration:{type:"reflection",prompt:"The ancient yogis said breath is the horse, mind is the rider. Where the breath goes, the mind follows. Where the breath stills, the mind stills. Did you experience this today?",deeperPrompt:"In the pause between inhale and exhale — there is no thought, no time, no identity. Just pure being. That gap is the same gap Ramana pointed to. The breath leads you there effortlessly.",closingWisdom:"Breath is the thread that connects the visible to the invisible, the body to the spirit."},dimension:"body",relatedConcepts:["pranayama","prana","breath","patanjali"]},{day:93,phase:"energy",title:"Muladhara: The Root",subtitle:"Survival, safety, and the right to exist",morningTeaching:{type:"concept",concept:"Root Chakra — Foundation of Being",keyPoints:["Muladhara (Root Support) sits at the base of the spine. It governs survival, safety, grounding, and your right to exist.","When balanced: you feel safe, grounded, present, stable. When blocked: anxiety, insecurity, hoarding, restlessness, financial fear.",`PSYCHOLOGY: Root chakra correlates with Maslow's first need (safety), attachment theory (secure base), and Polyvagal "safe" state.`,`Root wounds: "The world is not safe," "I don't belong," "I must fight to survive." These create the foundation of all other patterns.`,"Element: Earth. Color: Red. Mantra: LAM. Location: base of spine, perineum, legs, feet."],metaphor:"A tree with shallow roots falls in every storm. A tree with deep roots withstands hurricanes. Your root chakra IS your roots. How deep do they go?"},dayPractice:{type:"chakra-sense",instruction:'Today, bring awareness to the base of your spine and your connection to the earth. Walk barefoot if possible. Feel your weight on the ground. Place attention at the base of your spine and silently repeat "LAM" 7 times. Notice: do you feel stable? Safe? Grounded? Or untethered, anxious, floating?',duration:"10 minutes formal + grounding awareness throughout",checkpoints:["Do you feel safe in your body?","What is your relationship with security and survival?","Could you feel energy (or blockage) at the base of the spine?"]},eveningIntegration:{type:"reflection",prompt:"When in your life did you first feel unsafe? How has that moment shaped everything since — your career choices, relationships, vigilance?",deeperPrompt:'Your root chakra was formed in the first year of life. A baby that feels held is an adult who feels safe in the world. Were you held? If not — you can hold yourself now. Place your hands on your belly and say: "I am safe. I am here."',closingWisdom:"Before you can reach for the sky, you must know you stand on solid ground."},dimension:"body",relatedConcepts:["muladhara","root-chakra","safety","grounding"]},{day:94,phase:"energy",title:"Svadhisthana: The Sacral",subtitle:"Desire, creativity, and the flow of life",morningTeaching:{type:"concept",concept:"Sacral Chakra — The Seat of Creativity",keyPoints:["Svadhisthana (Her Own Dwelling Place) sits below the navel. It governs desire, creativity, pleasure, sexuality, and emotional flow.","When balanced: creativity flows, pleasure is enjoyed without guilt, emotions move freely. When blocked: guilt, sexual shame, creative blocks, emotional numbness.","PSYCHOLOGY: Correlates with the pleasure principle (Freud), flow states (Csikszentmihalyi), and emotional regulation.","Cultural suppression of the sacral chakra creates a society of productive but joyless people who feel guilty for wanting anything.","Element: Water. Color: Orange. Mantra: VAM. Location: lower abdomen, hips, reproductive organs."]},dayPractice:{type:"chakra-sense",instruction:'Today, focus on your sacral center (below navel). Notice your relationship with DESIRE and PLEASURE: Do you allow yourself to enjoy food fully? Do you feel guilty for wanting things? Is your creativity flowing or blocked? Silently repeat "VAM" 7 times with attention on the sacral area.',duration:"10 minutes formal + desire awareness throughout",checkpoints:["How is your relationship with pleasure?","Where do you feel creative blocks?","Could you sense energy in the lower abdomen?"]},eveningIntegration:{type:"reflection",prompt:"What desire are you suppressing because you were taught it was wrong? What would change if you allowed yourself to WANT what you actually want?",deeperPrompt:"The sacral chakra teaches: Life is meant to be savored, not endured. Desire itself is not the problem — unconscious desire is. Conscious desire is creativity.",closingWisdom:"The river of life wants to flow through you. Stop damming it with guilt."},dimension:"body",relatedConcepts:["svadhisthana","sacral-chakra","creativity","desire"]},{day:95,phase:"energy",title:"Manipura: The Solar Plexus",subtitle:"Will, power, and the fire of transformation",morningTeaching:{type:"concept",concept:"Solar Plexus Chakra — Personal Power",keyPoints:["Manipura (City of Jewels) sits at the solar plexus. It governs will, power, self-esteem, and personal identity.","When balanced: confidence without arrogance, healthy boundaries, disciplined action. When blocked: powerlessness, shame, rage, control issues, digestive problems.","PSYCHOLOGY: This is where self-esteem lives. Every time someone shamed you, they attacked your Manipura.","Manipura's fire (Agni) digests not only food but also EXPERIENCES — it processes and transforms what you take in.","Element: Fire. Color: Yellow. Mantra: RAM. Location: solar plexus, stomach, upper abdomen."]},dayPractice:{type:"chakra-sense",instruction:"Place your hand on your solar plexus (just below the ribcage). Breathe fire into it — imagine golden heat building there. Throughout today, notice: when do you give your power away? When do you feel strong? When do you feel small? The solar plexus CONTRACTS when power is threatened and EXPANDS when power is claimed.",duration:"10 minutes formal + power awareness throughout",checkpoints:["When did your power expand today?","When did you give your power away?","What does personal power feel like in the body?"]},eveningIntegration:{type:"reflection",prompt:"Who in your life diminished your sense of power? Can you reclaim it now — not through aggression but through awareness?",deeperPrompt:'True power is not dominance over others. Sadhguru: "If you align your personal will with the will of existence, there is nothing you cannot do."',closingWisdom:"You were never powerless. You were only told you were — and you believed it."},dimension:"body",relatedConcepts:["manipura","solar-plexus","personal-power","agni"]},{day:96,phase:"energy",title:"Anahata: The Heart Center",subtitle:"Love that needs no reason — the bridge between earth and sky",morningTeaching:{type:"concept",concept:"Heart Chakra — Unconditional Love",keyPoints:["Anahata (Unstruck Sound) sits at the center of the chest. It is the middle chakra — the bridge between the lower (physical) and upper (spiritual) centers.","When balanced: unconditional love, compassion, forgiveness, deep connection. When blocked: grief, loneliness, bitterness, inability to trust or forgive.",`Neem Karoli Baba's ENTIRE teaching was heart: "Love everyone, serve everyone, remember God." His path was pure Anahata.`,`The "unstruck sound" is love without cause — love that doesn't need an object or reason. It is the heart's natural state when cleared of grief.`,"Element: Air. Color: Green. Mantra: YAM. Location: center of chest, heart, lungs, arms, hands."]},dayPractice:{type:"chakra-sense",instruction:`Place your hand over your heart center (middle of chest). Breathe softly. Repeat "YAM" 7 times. Now think of someone you love easily. Feel the heart open. Then think of someone who hurt you. Notice the heart close. Today's practice: can you keep the heart open even when the mind has reasons to close it?`,duration:"10 minutes formal + heart-openness throughout",checkpoints:["Could you feel the heart physically opening and closing?","What closes your heart most reliably?","Could you keep it open toward someone difficult?"]},eveningIntegration:{type:"reflection",prompt:'Neem Karoli Baba was asked: "How do I meditate?" He said: "Meditate like Christ." They asked: "How did Christ meditate?" He said: "He lost himself in love."',deeperPrompt:"What grief is your heart still carrying? Who have you not forgiven — not for their sake, but for the sake of your own open heart?",closingWisdom:"The heart that has been broken open is the most powerful force in the universe. It has nothing left to protect."},dimension:"emotion",relatedConcepts:["anahata","heart-chakra","love","neem-karoli-baba"]},{day:97,phase:"energy",title:"Vishuddha: The Throat",subtitle:"Truth, expression, and the courage to speak your reality",morningTeaching:{type:"concept",concept:"Throat Chakra — Authentic Expression",keyPoints:["Vishuddha (Pure) sits at the throat. It governs expression, truth, communication, and creative voice.","When balanced: you speak your truth without aggression, listen deeply, express creatively. When blocked: fear of speaking, lying, gossip, thyroid issues, neck tension.",`Every word you swallowed, every truth you didn't speak, every time you said "I'm fine" when you weren't — it's stored here.`,"The throat chakra connects heart knowing to verbal expression. Many people feel truth but cannot VOICE it.","Element: Ether/Space. Color: Blue. Mantra: HAM. Location: throat, neck, jaw, mouth, thyroid."]},dayPractice:{type:"chakra-sense",instruction:`Today, notice EVERY time you suppress your truth: agreeing when you disagree, saying "fine" when you're not, holding back a compliment, swallowing anger. For at least ONE moment, speak something you would normally suppress. Notice: what happens in your throat when you speak truth vs. swallow it?`,duration:"1 truth-speaking moment + throat awareness throughout",checkpoints:["How many times did you suppress your voice today?","What happened when you spoke a truth you normally swallow?","Do you carry chronic tension in your throat/jaw/neck?"]},eveningIntegration:{type:"reflection",prompt:"What is the biggest truth you are not speaking in your life right now? To whom? What would happen if you did?",deeperPrompt:'Gandhi: "Truth is God." Not a particular truth, but the commitment to truthfulness itself. What would your life look like if you committed to speaking only truth for one week?',closingWisdom:"Your throat knows what your mind censors. Give it permission to speak."},dimension:"body",relatedConcepts:["vishuddha","throat-chakra","truth","expression"]},{day:98,phase:"energy",title:"Ajna: The Third Eye",subtitle:"Intuition, insight, and inner seeing",morningTeaching:{type:"concept",concept:"Third Eye Chakra — Inner Vision",keyPoints:["Ajna (Command) sits between the eyebrows. It governs intuition, insight, imagination, and inner vision.","When balanced: clear intuition, trust in inner knowing, ability to see beyond appearances. When blocked: confusion, indecision, nightmares, headaches.",'Sadhguru: "The third eye is not a mystical thing. It is the eye of perception that allows you to see dimensions beyond the physical."',"In yogic anatomy, the Ajna is where the three main nadis (Ida, Pingala, Sushumna) converge — making it the seat of unified perception.","Element: Light/Mind. Color: Indigo. Mantra: OM. Location: between eyebrows, pineal gland."],scienceNote:'The pineal gland (at the location of the Ajna chakra) produces melatonin and DMT, both associated with visionary states. Descartes called it "the seat of the soul." It is photosensitive even inside the skull.'},dayPractice:{type:"chakra-sense",instruction:'Close your eyes. Bring attention to the point between your eyebrows. Gently focus there without straining. Repeat "OM" 7 times, feeling the vibration in the center of the head. Throughout the day, before any decision, close your eyes briefly and check: what does your INNER EYE see? Trust the first image or impression.',duration:"10 minutes formal + intuition checks throughout",checkpoints:["Could you sense the Ajna point (between eyebrows)?","Did you receive any intuitive impressions when you checked?","What is the difference between thinking about something and SEEING it internally?"]},eveningIntegration:{type:"reflection",prompt:"Intuition is perception without the filter of the analytical mind. Today, did your inner eye show you anything your thinking mind would have missed?",deeperPrompt:"The third eye doesn't show you the future. It shows you the present — but from a dimension the two physical eyes cannot access.",closingWisdom:"You have always had a third eye. You just trusted the other two more."},dimension:"awareness",relatedConcepts:["ajna","third-eye","intuition","sadhguru","pineal"]},{day:99,phase:"energy",title:"Sahasrara: The Crown",subtitle:"Unity, transcendence, and the infinite",morningTeaching:{type:"concept",concept:"Crown Chakra — Union with the Infinite",keyPoints:["Sahasrara (Thousand-Petaled Lotus) sits at the crown of the head. It governs transcendence, unity, and cosmic consciousness.","When active: sense of oneness, dissolution of separate self, divine connection, ecstasy. This is samadhi in yogic terms.",'This chakra cannot be "opened" by effort. It opens naturally when all other chakras are balanced — like a flower blooming.',"Shiva sits at the crown. Shakti (kundalini) rises from the root. Their union at the crown IS enlightenment in Tantric yoga.","Element: Beyond elements — pure consciousness. Color: Violet/White/Gold. Mantra: Silence. Location: top of the head, fontanelle."]},dayPractice:{type:"chakra-sense",instruction:"Today, bring awareness to the top of your head. Can you feel a subtle sensation there? Warmth? Tingling? Openness? Practice bringing attention from the root (base of spine) upward through each chakra to the crown. Visualize energy rising like warm light through all 7 centers. Rest at the crown.",duration:"15 minutes of full-spine meditation",checkpoints:["Could you feel sensation at the crown?","What happened when you moved energy from root to crown?","Was there any sense of expansion or dissolution at the crown?"]},eveningIntegration:{type:"reflection",prompt:'Have you ever had a moment — perhaps in nature, in love, in crisis — where the sense of "separate me" dissolved and you felt ONE with everything? That was Sahasrara opening spontaneously.',deeperPrompt:"The crown doesn't connect you to God. It reveals you were never separate from God. Separation was the dream. Unity is reality.",closingWisdom:"The thousand-petaled lotus blooms not through effort but through the sun of awareness. Let it bloom."},dimension:"awareness",relatedConcepts:["sahasrara","crown-chakra","samadhi","unity"]},{day:100,phase:"energy",title:"Kundalini: The Sleeping Serpent",subtitle:"The coiled potential at the base of your spine",morningTeaching:{type:"concept",concept:"Kundalini Shakti",keyPoints:["Kundalini is the dormant cosmic energy coiled 3.5 times at the base of the spine (Muladhara).","When awakened, it rises through the Sushumna nadi (central channel), piercing each chakra, until it reaches the crown where Shakti meets Shiva.","Spontaneous kundalini experiences: involuntary body movements, intense heat, visions, emotional purging, bliss states.","WARNING: Forced kundalini awakening without proper preparation is dangerous. True kundalini rises naturally through purification, not force.",'Sadhguru: "Kundalini is not something to be raised. It is something to be made aware of. It is always active — but below your threshold of perception."'],scienceNote:"Kundalini symptoms overlap with documented neurological phenomena: paresthesia, autonomic arousal, myoclonic jerks, and altered states. Whether you frame it as energy or neurology — the experience is real and documented across cultures."},dayPractice:{type:"chakra-sense",instruction:"Today is OBSERVATION ONLY — no forced awakening. Sit quietly and bring attention to the base of your spine. Simply be present there. Notice any sensations: warmth, pulsing, tingling, nothing. Then slowly, with each breath, imagine that base-point gently warming — like embers being breathed upon. Don't force. Just observe and invite.",duration:"15 minutes of gentle base-awareness",checkpoints:["What did you sense at the base of the spine?","Did any spontaneous sensations arise elsewhere (heat, tingling, emotion)?","Could you feel the connection between the base and the crown?"]},eveningIntegration:{type:"integration",prompt:"Day 100 of 118. You have traveled from unconscious autopilot to sensing the kundalini serpent at the base of your spine. This is not small. Honor the journey.",deeperPrompt:"The yogis say kundalini awakening is not a goal — it is a byproduct of consciousness becoming so clear that energy has nowhere to hide. Your 100 days of awareness may already be stirring what sleeps.",closingWisdom:"The serpent sleeps because you sleep. As you awaken, so does she."},dimension:"body",relatedConcepts:["kundalini","shakti","sushumna","awakening"]},{day:101,phase:"energy",title:"Nadis: The Energy Channels",subtitle:"Ida, Pingala, and Sushumna — the rivers of life force",morningTeaching:{type:"concept",concept:"The Three Main Nadis",keyPoints:["The body has 72,000 nadis (energy channels). Three are primary: Ida (left/lunar/feminine), Pingala (right/solar/masculine), and Sushumna (central/neutral).","Ida governs rest, intuition, creativity, the parasympathetic system. Pingala governs action, logic, heat, the sympathetic system.","Most people are stuck in one: too much Pingala (stressed, driven) or too much Ida (passive, dreamy).","Sushumna is the CENTRAL channel — activated only when Ida and Pingala are balanced. Kundalini rises through Sushumna.","Nadi Shodhana (alternate nostril breathing) is the ancient technique for balancing Ida and Pingala."]},dayPractice:{type:"breath-watch",instruction:"Practice Nadi Shodhana: Close right nostril, inhale through left (4 counts). Close both, hold (4 counts). Release right, exhale through right (4 counts). Inhale right (4). Hold (4). Release left, exhale left (4). That's one round. Do 7 rounds. Then sit and feel: which side of your body feels different?",duration:"10 minutes Nadi Shodhana + awareness throughout",checkpoints:["Did you feel a difference between left and right channels?","Which nostril was more dominant before the practice?","After the practice, did you feel more balanced?"]},eveningIntegration:{type:"reflection",prompt:"Which nadi dominates your life? Ida (you're passive, dreamy, emotional) or Pingala (you're driven, hot, analytical)? What would balance look like?",deeperPrompt:"When Ida and Pingala are balanced, Sushumna opens. And when Sushumna opens — meditation happens effortlessly. It is not something you DO. It is something that happens when conditions are right.",closingWisdom:"Balance the sun and moon within you, and the central fire ignites on its own."},dimension:"body",relatedConcepts:["nadis","ida","pingala","sushumna","nadi-shodhana"]},{day:102,phase:"energy",title:"The Trimurti: Creation, Preservation, Destruction",subtitle:"Brahma, Vishnu, Shiva — the cosmic cycle within you",morningTeaching:{type:"concept",concept:"The Three Divine Functions",keyPoints:["Hindu cosmology describes three divine functions: Brahma (creation), Vishnu (preservation), and Shiva (destruction/transformation).","These are not three separate gods — they are three MOVEMENTS of one reality, happening simultaneously.","In YOU: Brahma creates thoughts, identities, desires. Vishnu sustains habits, relationships, patterns. Shiva destroys what no longer serves.","Most people are stuck in Vishnu mode — preserving, maintaining, holding on. Growth requires activating Brahma (creating new) AND Shiva (destroying old).","Your loops are Vishnu energy misapplied — preserving patterns that need Shiva's fire. Your breakthroughs are Shiva energy — burning what is false."],metaphor:"Every sunrise is Brahma. Every day is Vishnu. Every sunset is Shiva. And then — Brahma again. The cycle never stops. Your consciousness works the same way: constantly creating, sustaining, and dissolving. The question is: are you creating and destroying CONSCIOUSLY?"},dayPractice:{type:"observation",instruction:"Today, observe all three divine functions in yourself: (1) BRAHMA: What did you CREATE today — a thought, a conversation, an idea? (2) VISHNU: What did you SUSTAIN today — a habit, a relationship, a belief? (3) SHIVA: What died or ended today — a mood, a plan, an expectation? Map at least 3 examples of each.",duration:"Throughout the day",checkpoints:["Which divine function is most active in your life right now?","What do you need to let Shiva destroy that Vishnu is holding on to?","What does Brahma want to create that you haven't given permission for?"]},eveningIntegration:{type:"integration",prompt:"If Shiva could visit your life tonight and destroy ONE thing that no longer serves you — what should he burn?",deeperPrompt:"The Trimurti is not mythology. It is the deepest insight into how reality works: everything is constantly being created, sustained, and destroyed. Your resistance to this cycle IS your suffering.",closingWisdom:"Let Shiva dance on what must die so Brahma can create what must be born."},dimension:"awareness",relatedConcepts:["trimurti","brahma","vishnu","shiva","cycles"]},{day:103,phase:"energy",title:"The Occult & Subtle Realms",subtitle:"What lies beyond the five senses — the territories your science hasn't mapped",morningTeaching:{type:"concept",concept:"Beyond the Known",keyPoints:["The five senses detect less than 1% of the electromagnetic spectrum. There is vastly more to reality than what you can see, hear, or touch.","Yogic tradition describes subtle realms: Astral body (sukshma sharira), causal body (karana sharira), and akashic records (collective memory field).",`Synchronicities, déjà vu, precognitive dreams, sensing someone's presence — these are not "woo." They are the subtle body picking up information the physical senses miss.`,`Yogananda: "Intuition is the soul's power of knowing God. To go beyond the ordinary senses, you must develop the sixth sense."`,"Approach with OPEN SKEPTICISM: neither belief nor dismissal. Direct experience is the only teacher here."],scienceNote:`Quantum physics demonstrates non-locality (particles affect each other across any distance), observer effects (consciousness affects physical reality), and the measurement problem (reality behaves differently when observed). The "occult" may be physics we haven't formalized yet.`},dayPractice:{type:"observation",instruction:`Today, pay attention to the UNEXPLAINED: coincidences, feelings about people that turn out to be accurate, moments where you "just know" something. Don't force it. Don't dismiss it. Simply notice: is there a layer of knowing beyond the five senses? Document any subtle perceptions without judgment.`,duration:"Throughout the day — quiet observation",checkpoints:['Did anything "unexplainable" happen today?',"Have you ever had a dream that came true?","Do you sense energy from certain places or people?"]},eveningIntegration:{type:"reflection",prompt:`What have you experienced that you couldn't explain — and dismissed because "it's not rational"? What if your rational mind is the smallest room in a very large house?`,deeperPrompt:"There are more things in heaven and earth than are dreamt of in your philosophy. What would change if you allowed 5% more mystery into your worldview?",closingWisdom:"The map is not the territory. Your five senses map less than 1% of the territory. Walk humbly in the unmapped 99%."},dimension:"awareness",relatedConcepts:["subtle-realms","occult","akashic","yogananda","quantum"]},{day:104,phase:"energy",title:"Energy Psychology & Healing",subtitle:"How energy blocks create mental patterns — and how awareness heals both",morningTeaching:{type:"concept",concept:"The Energy-Psychology Connection",keyPoints:["Chakra blockages create predictable psychological patterns: blocked root = anxiety. Blocked sacral = guilt. Blocked solar plexus = shame.","Blocked heart = grief. Blocked throat = dishonesty. Blocked third eye = confusion. Blocked crown = disconnection.","Healing doesn't start in the mind. It starts in the energy body. Clear the blockage, and the psychological pattern LOOSENS automatically.","This is why body-based therapies (yoga, somatic experiencing, breathwork) often work faster than talk therapy.",'Sadhguru: "If you take charge of your energies, you will not know any limitation."']},dayPractice:{type:"chakra-sense",instruction:"Do a full 7-chakra scan today. For each chakra: (1) Bring attention there. (2) Notice: open or blocked? Warm or cold? Flowing or stuck? (3) Connect the physical sensation to the psychological pattern (anxiety → root, guilt → sacral, etc.). (4) Breathe into any blocked area for 1 minute. (5) Notice any shifts.",duration:"20 minutes — full chakra diagnostic",checkpoints:["Which chakra felt most blocked?","Could you connect energy sensations to psychological patterns?","Did breathing into a blocked area create any shift?"]},eveningIntegration:{type:"integration",prompt:"Your chakra map is your psychological map read in a different language. Now you can read both. What is the most important energy-psychology connection you discovered?",deeperPrompt:"Healing is not adding something new. It is removing what blocks the natural flow. Your energy body WANTS to be clear. It knows how to heal. You just need to stop interfering.",closingWisdom:"The body heals a cut without your thinking about it. The energy body heals a blockage the same way — when you bring awareness and stop resisting."},dimension:"body",relatedConcepts:["chakra-psychology","energy-healing","somatic","sadhguru"]},{day:105,phase:"energy",title:"Energy Phase Complete",subtitle:"From matter to energy to consciousness — the journey inward",morningTeaching:{type:"review",concept:"Phase 7 Integration",keyPoints:["In 15 days you have mapped your energy body: prana, 7 chakras, kundalini, nadis, the Trimurti cycle, and the subtle realms.","You can now work with THREE layers: physical body (Phases 1-4), psychological patterns (Phase 5-6), and energy (Phase 7).","These are not separate — they are one system viewed from three angles. A chakra blockage IS a psychological pattern IS a body tension.","The final phase weaves everything together through the Four Yoga Paths — your personal blueprint for living as consciousness.",`Einstein: "Everything is energy and that's all there is. Match the frequency of the reality you want and you cannot help but get that reality."`]},dayPractice:{type:"journaling",instruction:"Create your ENERGY MAP: draw a simple body outline and mark all 7 chakras. For each, write: (1) Open/blocked? (2) What psychological pattern correlates? (3) What life area does it affect? (4) What would healing look like here? This is your energy blueprint.",duration:"20 minutes",checkpoints:["What does your energy map reveal?","Which chakra needs the most attention?","How does your energy map connect to your loop map from Phase 5?"]},eveningIntegration:{type:"integration",prompt:"You've journeyed from body to emotion to mind to energy. The next phase asks: now that you see the whole system — how do you LIVE from this awareness?",deeperPrompt:'Vivekananda: "All the powers in the universe are already ours. It is we who have put our hands before our eyes and cry that it is dark."',closingWisdom:"You are not a body having a spiritual experience. You are consciousness having a human experience. The energy body is where they meet."},dimension:"awareness",relatedConcepts:["integration","energy-map","vivekananda"]}],l=[{day:106,phase:"integration",title:"The Four Paths of Yoga",subtitle:"Every seeker finds their way — which is yours?",morningTeaching:{type:"concept",concept:"Overview of the Four Yoga Paths",keyPoints:["The Bhagavad Gita teaches four paths to liberation — each suited to a different temperament:",'JNANA YOGA — The Path of Knowledge. For the intellectual, the questioner, the philosopher. "Who am I?" Liberation through understanding.',"BHAKTI YOGA — The Path of Devotion. For the emotional, the lover, the heart-centered. Liberation through love and surrender.","KARMA YOGA — The Path of Action. For the doer, the servant, the engaged. Liberation through selfless action without attachment to results.","RAJA YOGA — The Royal Path. For the disciplined, the meditator, the scientist of consciousness. Liberation through meditation and the 8 limbs of Patanjali.",'Vivekananda: "Each yoga is suited to a particular temperament. In reality, every person uses a combination — but one path leads."'],metaphor:"Four rivers flow to the same ocean. The Jnani swims through knowledge. The Bhakta floats on love. The Karma Yogi rows with selfless action. The Raja Yogi navigates by the stars of meditation. Different rivers. Same ocean."},dayPractice:{type:"journaling",instruction:'Reflect: Which path resonates MOST deeply? (1) Do you approach life through UNDERSTANDING — always asking "why?" → Jnana. (2) Do you approach through FEELING — moved by love, beauty, devotion? → Bhakti. (3) Do you approach through DOING — service, work, contribution? → Karma. (4) Do you approach through STILLNESS — meditation, inner discipline? → Raja. Write about each and notice which lights up.',duration:"15 minutes reflection",checkpoints:["Which path felt most natural to you?","Which path felt most foreign?","Can you see elements of all four in your life?"]},eveningIntegration:{type:"reflection",prompt:"Krishna says all four paths are valid. There is no hierarchy. The best path is the one that matches YOUR nature. What is your nature?",deeperPrompt:"The four paths are not separate destinations. They are four lanes on the same highway. As you evolve, you naturally begin to use all four — but one leads.",closingWisdom:"The path chooses you as much as you choose the path. Listen to what calls."},dimension:"awareness",relatedConcepts:["yoga-paths","jnana","bhakti","karma","raja"]},{day:107,phase:"integration",title:"Jnana Yoga: The Path of Knowledge",subtitle:"Liberation through understanding — not intellectual, but LIVED knowing",morningTeaching:{type:"concept",concept:"Jnana Yoga",keyPoints:["Jnana Yoga is the path of discrimination (Viveka) between the real and the unreal.","Adi Shankara formalized it: Brahman (consciousness) alone is real. The world is Mithya (apparent reality, not ultimate reality). The individual self IS Brahman.",'The Jnani asks: "What is permanent? What is impermanent? I am what is permanent." This is not intellectual — it is a lived investigation.',"The four qualifications (Sadhana Chatushtaya): (1) Viveka — discrimination. (2) Vairagya — dispassion. (3) Shatsampatti — six virtues. (4) Mumukshutva — burning desire for liberation.",'Vivekananda: "The Jnana Yogi says: I am the Self, already free, already pure. Ignorance created the illusion of bondage."']},dayPractice:{type:"self-inquiry",instruction:'Today, practice Viveka (discrimination) in real-time. For every experience, ask: "Is this permanent or impermanent?" Your mood → impermanent. Your body sensation → impermanent. The awareness KNOWING the experience → permanent. Spend the day sorting real from unreal.',duration:"Discrimination practice throughout the day",checkpoints:["What did you find that is permanent (unchanging)?","How does it feel to recognize most of experience as impermanent?","Does recognizing impermanence create despair or freedom?"]},eveningIntegration:{type:"reflection",prompt:"The Jnani does not reject the world. The Jnani sees THROUGH the world to the reality behind it. What reality did you glimpse behind appearances today?",deeperPrompt:`Shankara: "The universe is Brahman's dream. The dreamer is real. The dream is real as dream, unreal as absolute." Can you hold both — living fully in the dream while knowing the dreamer?`,closingWisdom:"Knowledge is not about accumulating information. It is about seeing through illusion to what remains."},dimension:"awareness",relatedConcepts:["jnana-yoga","viveka","shankara","advaita"]},{day:108,phase:"integration",title:"Day 108: The Sacred Number",subtitle:"A pause — 108 beads on the mala of your transformation",morningTeaching:{type:"concept",concept:"The Significance of 108",keyPoints:["108 is sacred across traditions: 108 beads on a mala, 108 Upanishads, 108 names of Shiva, the sun's diameter is 108× Earth's.","Today is YOUR 108th day. You have done something extraordinary: 108 days of conscious attention to your inner world.","This is not a number. This is EVIDENCE that you are no longer the same person who started. Every day of awareness has reshaped your neural pathways.","Jnana Yoga deepening: you've proven through experience (not belief) that you are not your thoughts, emotions, body, or patterns. What ARE you?","Today, celebrate not what you've learned but what you've BECOME. And recognize: you haven't become anything new. You've uncovered what was always here."]},dayPractice:{type:"witness",instruction:"Today, practice 10 minutes of pure presence — no technique, no method, no inquiry. Just BE. Let everything be as it is. Thoughts, emotions, sensations — all welcome, none pursued. This is the culmination of Jnana: not knowing about reality, but BEING reality.",duration:"10 minutes pure being + celebratory awareness",checkpoints:["Could you simply BE without doing anything?","What is the quality of pure presence?","How different is today's awareness from Day 1?"]},eveningIntegration:{type:"integration",prompt:"108 days. Thousands of observations, hundreds of insights, dozens of transformations. And yet — the simplest truth: you are here. You are aware. That hasn't changed since Day 1. Only the clarity has deepened.",deeperPrompt:'The mala (prayer beads) has 108 beads — and then a single "guru bead" that is not counted. YOU are the guru bead. Everything points back to you.',closingWisdom:"You've traveled 108 days to arrive exactly where you started — but for the first time, you see where you are."},dimension:"awareness",relatedConcepts:["sacred-108","jnana","pure-being","milestone"]},{day:109,phase:"integration",title:"Bhakti Yoga: The Path of Devotion",subtitle:"Surrender, love, and the dissolution of ego through the heart",morningTeaching:{type:"concept",concept:"Bhakti Yoga — Love as Liberation",keyPoints:["Bhakti is the path where the ego dissolves not through knowledge but through LOVE so total that the lover disappears.",'Neem Karoli Baba embodied this: he saw Ram (God) in everyone. A thief came to rob him. He wept: "Ram has come in the form of a thief!"',`Rumi: "Love is the bridge between you and everything." The Bhakta doesn't understand God. The Bhakta IS love.`,'Krishna in the Gita: "Of all yogis, the one who worships Me with faith and love, I consider the most devoted." (6.47)',"Bhakti is not religious devotion to an idol. It is the heart opening so completely that the sense of separation from existence dissolves.","Chaitanya Mahaprabhu, Mirabai, Tukaram — all Bhaktas who achieved liberation through devotion alone."]},dayPractice:{type:"gratitude",instruction:'Today, practice radical devotion — not to a deity but to LIFE ITSELF. Look at every person as sacred. Every tree as miraculous. Every meal as an offering. When you see anyone, silently say: "The divine in me sees the divine in you." Feel your heart throughout the day.',duration:"Entire day as devotional practice",checkpoints:["Could you see the sacred in the ordinary?","Did your heart open when you practiced seeing divine in others?","How does devotion feel different from analysis?"]},eveningIntegration:{type:"surrender",prompt:'Neem Karoli Baba said: "Love everyone. Serve everyone. Remember God." Could you live by this? Not as a rule — as an overflow of the heart?',deeperPrompt:`Rumi: "I have lived on the lip of insanity, wanting to know reasons, knocking on a door. It opens. I've been knocking from the inside." The Bhakta discovers: the love you seek is the love you ARE.`,closingWisdom:"Love is not something you find. Love is what you become when you stop defending yourself."},dimension:"emotion",relatedConcepts:["bhakti-yoga","devotion","neem-karoli-baba","rumi","love"]},{day:110,phase:"integration",title:"Bhakti in Practice",subtitle:"Finding the sacred in the ordinary — devotion as a way of seeing",morningTeaching:{type:"practice-intro",concept:"Living Bhakti",keyPoints:["Bhakti in daily life: every act becomes an offering. Cooking becomes sacred. Work becomes worship. Conversation becomes communion.",'The key shift: from "I am doing this FOR ME" to "this is being done THROUGH me."','Ram Dass (student of Neem Karoli Baba): "We are all just walking each other home." Every person you meet is a fellow traveler.',"Kirtan (devotional chanting), seva (selfless service), and puja (offering) are not rituals — they are expressions of a heart that overflows.","Modern Bhakti: gratitude practice, loving-kindness meditation, seeing beauty in the mundane, serving without recognition."]},dayPractice:{type:"gratitude",instruction:"Choose ONE act today and perform it as a devotional offering — not for reward, not for the result, but as an expression of love for existence itself. Cook a meal as though feeding God. Clean a room as though preparing a temple. Have a conversation as though speaking with the divine in human form.",duration:"One act of devotion + gratitude throughout",checkpoints:["How did the act feel different when done as an offering?",'Can you feel the shift from "doing for self" to "offering to life"?',"Where do you already practice Bhakti without knowing it?"]},eveningIntegration:{type:"gratitude-deep",prompt:"Name 10 things you are grateful for — but not the obvious ones. The feel of fabric. The fact that your eyes work. The stranger who held the door. Find gratitude in what you normally overlook.",deeperPrompt:`Meister Eckhart: "If the only prayer you ever say in your whole life is 'thank you,' that would suffice." Gratitude IS devotion.`,closingWisdom:"When the heart is full, the entire world becomes a temple."},dimension:"emotion",relatedConcepts:["bhakti-practice","seva","gratitude","ram-dass"]},{day:111,phase:"integration",title:"Karma Yoga: The Path of Action",subtitle:"Selfless action without attachment to results — the Gita's central teaching",morningTeaching:{type:"concept",concept:"Karma Yoga — Action as Liberation",keyPoints:[`Krishna's teaching to Arjuna: "You have the right to action alone, never to its fruits." (Gita 2.47) This is Karma Yoga.`,"Karma Yoga is NOT renouncing action. It is renouncing ATTACHMENT to the result while giving your BEST to the action.","The ego acts for reward: praise, money, recognition. The Karma Yogi acts because the action itself is right — outcome is irrelevant.","Gandhi was the supreme Karma Yogi: tireless action, zero attachment to personal gain, every act in service of truth.","The paradox: when you stop clinging to results, your actions become MORE effective, not less. You are freed from fear of failure."],metaphor:"A musician who plays for applause plays differently than one who plays for the love of music. The first is imprisoned by the audience. The second is free. Both play — but only one is a Karma Yogi."},dayPractice:{type:"observation",instruction:"Today, do EVERY action without checking for results. Send the email — don't check for replies. Do the work — don't seek praise. Help someone — don't wait for thanks. Cook the meal — don't fish for compliments. Notice how the mind SCREAMS for feedback. Let it scream. Keep acting.",duration:"Every action today — detach from outcomes",checkpoints:["How many times did you catch yourself checking for results?","Could you feel the freedom in acting without attachment?","What happens to the quality of your work when you stop worrying about the outcome?"]},eveningIntegration:{type:"reflection",prompt:"Krishna's radical teaching: it is not about what you do. It is about the CONSCIOUSNESS behind the action. The same action done with ego is bondage. Done without ego, it is liberation.",deeperPrompt:"What if your entire day's work was an offering — to life, to truth, to the world — with zero expectation of return? Would you still do it? THAT answer reveals your soul.",closingWisdom:"Act. But let the action flow through you, not from you. Be the instrument, not the musician."},dimension:"awareness",relatedConcepts:["karma-yoga","gita","detachment","gandhi","selfless-action"]},{day:112,phase:"integration",title:"Karma in Practice",subtitle:"Working without ego — serving without seeking",morningTeaching:{type:"practice-intro",concept:"Living Karma Yoga",keyPoints:["Karma Yoga in daily life: your JOB becomes yoga. Your PARENTING becomes yoga. Your cooking, cleaning, driving — all yoga.",'The key: offer every action to something larger than yourself. Not "I am working for my salary" but "I am contributing through my work."',"Seva (selfless service) is the purest form: serve without recognition, without credit, without anyone knowing.",'Mother Teresa: "Not all of us can do great things. But we can do small things with great love." Small acts with big awareness.',"The test of Karma Yoga: can you do the MOST mundane task with the same presence and care as the most important?"]},dayPractice:{type:"observation",instruction:"Perform ONE anonymous act of service today — something that nobody will know you did. Hold a door, pick up trash, send an encouraging message, leave a tip with a kind note. The EGO will want credit. Do it anyway. Notice: how does INVISIBLE kindness feel different from visible kindness?",duration:"One anonymous act of service + mindful action throughout",checkpoints:["Could you serve without recognition?","What did the ego say when it couldn't claim credit?","Did you discover that the act itself was the reward?"]},eveningIntegration:{type:"reflection",prompt:'Gandhi: "The best way to find yourself is to lose yourself in the service of others." Did you lose yourself in service today? Even for a moment?',deeperPrompt:`Karma Yoga is the antidote to the ego's central demand: "What's in it for me?" What if you lived one week where that question never arose? Who would you be?`,closingWisdom:"The universe rewards the one who gives without keeping score. Not as cosmic karma — but as liberation from the prison of self-interest."},dimension:"awareness",relatedConcepts:["seva","karma-practice","gandhi","selfless-service"]},{day:113,phase:"integration",title:"Raja Yoga: The Eight Limbs of Patanjali",subtitle:"The systematic science of consciousness — 2,500 years, still unmatched",morningTeaching:{type:"concept",concept:"Patanjali's Ashtanga (Eight Limbs)",keyPoints:["Patanjali's Yoga Sutras outline 8 limbs (Ashtanga) — a complete technology for human liberation:","1. YAMA — External ethics: non-violence (ahimsa), truthfulness (satya), non-stealing (asteya), continence (brahmacharya), non-attachment (aparigraha)","2. NIYAMA — Internal discipline: cleanliness (saucha), contentment (santosha), austerity (tapas), self-study (svadhyaya), surrender (ishvara pranidhana)","3. ASANA — Steady, comfortable posture for meditation","4. PRANAYAMA — Mastery of life force through breath","5. PRATYAHARA — Withdrawal of senses (turning attention inward)","6. DHARANA — Concentration (one-pointed focus)","7. DHYANA — Meditation (sustained, effortless awareness)","8. SAMADHI — Absorption (subject-object duality dissolves)"],scienceNote:"The 8 limbs map onto modern psychology: Yama/Niyama = behavioral ethics, Asana = body readiness, Pranayama = nervous system regulation, Pratyahara = attention control, Dharana/Dhyana = focused attention meditation, Samadhi = flow states and peak experiences."},dayPractice:{type:"observation",instruction:"Today, consciously practice ALL 8 limbs as micro-practices: (1) Yama: one act of non-harm. (2) Niyama: one act of self-discipline. (3) Asana: 5 minutes of still sitting. (4) Pranayama: 3 minutes of conscious breathing. (5) Pratyahara: close eyes, withdraw senses for 2 minutes. (6) Dharana: concentrate on one object for 3 minutes. (7) Dhyana: let concentration soften into meditation. (8) Samadhi: if it arises, simply BE.",duration:"Full 8-limb micro-practice (~20 minutes) + integration throughout",checkpoints:["Which limb came most naturally?","Which limb was most challenging?","Did you experience the flow from concentration → meditation → absorption?"]},eveningIntegration:{type:"reflection",prompt:"Patanjali built a technology that has been tested by millions for 2,500 years. Which of the 8 limbs needs the most work in YOUR life? Where is the weak link in your chain?",deeperPrompt:"The 8 limbs are not sequential — they are simultaneous. A truly integrated practitioner lives all 8 every moment. Ethical, disciplined, embodied, breathing, interiorized, focused, meditative, absorbed. Is this possible?",closingWisdom:"Patanjali did not invent yoga. He systematized what consciousness already knew about itself."},dimension:"awareness",relatedConcepts:["raja-yoga","ashtanga","patanjali","eight-limbs"]},{day:114,phase:"integration",title:"Sadhguru's Inner Engineering",subtitle:"Making consciousness a practical technology for modern life",morningTeaching:{type:"concept",concept:"Inner Engineering — Modern Yoga",keyPoints:['Sadhguru bridges ancient yogic science with contemporary life. His teaching: "Yoga is not about bending your body. It is about bending the curve of your destiny."',"Inner Engineering's core: you are not the body, not the mind, not the emotions, not even the energy — you are the conscious presence behind all of them.",'Key principle: "Your experience of life is determined by how you ARE, not what happens to you."','The Isha Kriya: a simple 12-minute practice combining breath, awareness, and the thought "I am not the body, I am not even the mind."',"Sadhguru's integration: Jnana (clarity), Bhakti (inclusiveness), Karma (action), Raja (inner science) — all four paths in one living system.",'Practical teaching: "If you are joyful by your own nature, you will be a contribution to everyone around you."']},dayPractice:{type:"witness",instruction:'Practice the Isha Kriya essence: Sit comfortably. Eyes closed. Inhale, think: "I am not the body." Exhale, think: "I am not even the mind." Continue for 12 minutes. Then sit silently for 5 minutes, being whatever you ARE when you are neither body nor mind.',duration:"12 minutes Isha Kriya + 5 minutes silence",checkpoints:['What are you when you are "not the body, not even the mind"?',"Did the practice shift your state?","Could you carry that shift into daily activity?"]},eveningIntegration:{type:"reflection",prompt:'Sadhguru: "The most fundamental quality of your life is aliveness, not the content of your life." Are you more ALIVE today than Day 1? More aware? More awake?',deeperPrompt:"The yogic technologies are 5,000 years old. The human consciousness they address is timeless. You are using ancient tools to solve the eternal problem: suffering caused by misidentification.",closingWisdom:"You don't need to go to India. You don't need a guru. The entire technology is inside you, waiting to be activated by your own attention."},dimension:"awareness",relatedConcepts:["sadhguru","inner-engineering","isha-kriya","modern-yoga"]},{day:115,phase:"integration",title:"Your Dominant Path",subtitle:"Which yoga speaks to your deepest nature?",morningTeaching:{type:"concept",concept:"Finding Your Path",keyPoints:["By now, one path has likely called to you more strongly than the others. THIS IS YOUR ENTRY POINT — not your entire truth.","The thinking person starts with Jnana but must eventually open the heart (Bhakti). The feeling person starts with Bhakti but must eventually clarify the mind (Jnana).",'Vivekananda: "The ideal is to combine all four — each bringing the others into balance."',"Your dominant path is not a choice — it is a RECOGNITION. You don't choose the path. You recognize which one you've been walking all along.","The yoga path affinity in your consciousness profile reflects this: the system has been watching which path you naturally gravitate toward."]},dayPractice:{type:"journaling",instruction:"Write your YOGA PATH DECLARATION: (1) My dominant path is ___. (2) I know this because ___. (3) The path I most need to develop is ___. (4) My daily practice going forward will include: [morning practice, midday awareness, evening integration]. Design YOUR practice — not one given to you, but one born from your own understanding.",duration:"20 minutes",checkpoints:["Which path claimed you?","What does your personal practice look like?","Can you commit to this practice beyond Day 118?"]},eveningIntegration:{type:"integration",prompt:"Your path is unique. No one in history has walked exactly your path. Your combination of Jnana, Bhakti, Karma, and Raja is YOUR signature. Own it.",deeperPrompt:`Krishna's final teaching to Arjuna: "Abandon all dharmas and take refuge in Me alone. I shall free you from all sins. Do not grieve." (Gita 18.66) — the ultimate surrender beyond all paths.`,closingWisdom:"All paths lead to the same place. Walk yours with conviction and humility."},dimension:"awareness",relatedConcepts:["path-affinity","integration","personal-practice"]},{day:116,phase:"integration",title:"Integration Day",subtitle:"Weaving 115 days into a seamless fabric of awareness",morningTeaching:{type:"review",concept:"Full Integration",keyPoints:["You now carry the complete toolkit: Three Lenses (Head, Heart, Gut), Witness awareness, Chitta Vritti recognition, Guna sensitivity, Shadow work, Self-inquiry, Chakra awareness, and your Yoga Path.","These are not separate tools — they are different angles on ONE reality: your consciousness.",`Integration means: you don't "practice awareness." You ARE awareness, expressing through thoughts, feelings, body, energy, and action.`,"The daily cycle continues: Morning intention, Midday observation, Evening integration, Night surrender.","From now on, the AI generates your daily content based on YOUR profile, YOUR loops, YOUR V-Level, YOUR dominant path — personalized, alive, evolving."]},dayPractice:{type:"witness",instruction:"Today, live AS the integrated system. Don't choose one tool — let the right tool arise naturally. In a difficult conversation → Heart Lens + Shadow awareness. In a decision → Three Lens check + Gut intuition. In stress → Breath + Witness. Trust your 115 days of training. Let awareness be your default, not your practice.",duration:"The entire day — living integration",checkpoints:["Did the right awareness tool arise naturally in each situation?","Were you operating more from awareness than autopilot?","What percentage of your day was conscious vs unconscious?"]},eveningIntegration:{type:"integration",prompt:"You are no longer a student of awareness. You are a PRACTITIONER. What does that mean for how you live tomorrow, and the day after, and every day?",deeperPrompt:"The teacher-student relationship transforms. From now on, your inner awareness IS the teacher. The AI becomes a mirror, not a guide. You already know the way.",closingWisdom:"The practice is not separate from life. Life IS the practice. You are ready."},dimension:"awareness",relatedConcepts:["integration","living-practice","autonomous-awareness"]},{day:117,phase:"integration",title:"The Living Practice",subtitle:"From 118 days to the rest of your life",morningTeaching:{type:"concept",concept:"Embodiment — Making It Permanent",keyPoints:["Knowledge without embodiment is entertainment. Everything you've learned must now live in your BODY, your RELATIONSHIPS, your WORK.","The real test: can you maintain awareness in an argument? During heartbreak? Under pressure? When nobody is watching?","Your daily practice going forward: Morning (5 min intention + inquiry), Midday (3 awareness check-ins), Evening (5 min reflection + gratitude), Night (surrender).","The V-Level system continues to track your growth. The AI continues to personalize. But YOU are the engine now.",'Sadhguru: "Transformation should not be a goal. Transformation should be a way of life."']},dayPractice:{type:"journaling",instruction:"Write your CONSCIOUSNESS MANIFESTO: Who were you 117 days ago? Who are you now? What is your commitment going forward? What will you practice? What will you NOT go back to? This is your personal declaration of independence — from unconsciousness.",duration:"20 minutes",checkpoints:["What is the single biggest change in you?","What practice will you maintain daily?","What would it take to truly never go back to sleep?"]},eveningIntegration:{type:"reflection",prompt:'Ramana was asked: "What should I do after self-inquiry reveals the Self?" He said: "Just be." That is your instruction for the rest of your life.',deeperPrompt:"Tomorrow is Day 118 — not the end but the beginning. The foundation is built. The house of consciousness is yours to live in. Move in.",closingWisdom:"The seed was planted 117 days ago. The tree will grow for a lifetime. Trust the roots you've established."},dimension:"awareness",relatedConcepts:["embodiment","daily-practice","commitment"]},{day:118,phase:"integration",title:"The Beginning",subtitle:"This is not the end — it is the real beginning",morningTeaching:{type:"review",concept:"Graduation & Commencement",keyPoints:["Day 118. You have traveled through: Awakening (the observer is born), The Mind (understanding the head), The Heart (feeling without drowning), The Body (somatic intelligence), Loops & Samskaras (seeing the machinery), Self-Inquiry (who am I?), Energy & Chakras (the subtle body), and The Four Paths (your way forward).","You carry the wisdom of: Patanjali, Krishna, Ramana Maharshi, Vivekananda, Adi Shankara, Neem Karoli Baba, Sadhguru, Rumi, Viktor Frankl, Carl Jung, and countless others.","But the most important teaching you carry is the one that cannot be put into words: the direct EXPERIENCE of awareness, presence, and being.","The course ends. The journey does not. From today, every moment is your teacher. Every challenge is your practice. Every breath is your meditation.",`Neem Karoli Baba's final instruction: "Love everyone. Serve everyone. Remember God. Tell the truth."`]},dayPractice:{type:"witness",instruction:"Today, there is no practice. There is only LIVING. Go about your day with everything you've learned woven into your being — not as technique, but as WHO YOU ARE. If you forget and fall into autopilot — welcome. Notice that too. The practice includes forgetting and remembering. The practice IS life.",duration:"Your entire life, starting now",checkpoints:["Are you present right now?","Can you feel the difference between who you are today and who you were 118 days ago?","What is the first thing you want to do with your awake, conscious life?"]},eveningIntegration:{type:"surrender",prompt:"You arrived. Not at a destination — at yourself. Everything you sought was already here. The journey was not about getting somewhere. It was about removing what covered where you already were.",deeperPrompt:`Krishna's last words to Arjuna: "Now you have the knowledge. Do as you wish." (Gita 18.63) — the ultimate trust. Not "do as I say" but "do as you wish." Because NOW your wish comes from wisdom, not from conditioning.`,closingWisdom:"The journey of 118 days ends. The journey of a lifetime begins. You are awake. You are free. You always were. Now you know it. Go live."},dimension:"awareness",relatedConcepts:["graduation","beginning","living-practice","freedom"]}],o=[{id:"awakening",name:"The Awakening",subtitle:"Discovering the Observer Within",days:[1,14],description:"You have lived your entire life on autopilot — reacting, believing every thought, identifying with every emotion. These 14 days crack open the door. You will discover that there is something watching all of it. That discovery changes everything.",icon:"Eye",gradient:"from-violet-600 to-indigo-700",keyOutcomes:["Understand what observation really means",'Experience the "witness gap" for the first time',"Learn the difference between thinking and awareness","Establish a daily practice rhythm"]},{id:"mind",name:"The Mind Lens",subtitle:"Understanding Your Mental Machinery",days:[15,30],description:"The mind is not you — it is a tool that has taken over. In these 16 days, you will learn how the Head Lens works: thought patterns, cognitive biases, the stories you tell yourself, and the prison of identification. You will learn to use the mind instead of being used by it.",icon:"Brain",gradient:"from-cyan-600 to-blue-700",keyOutcomes:["Map your dominant thought patterns","Identify cognitive biases in real-time","Understand rumination vs. productive thinking","Experience thought-free gaps naturally"]},{id:"heart",name:"The Heart Lens",subtitle:"Emotional Intelligence Beyond Concepts",days:[31,45],description:"Emotions are not the enemy — suppression is. These 15 days teach you to feel fully without being hijacked. You will learn where emotions live in the body, how reactions form before you are aware of them, and how to transform emotional energy instead of acting it out or pushing it down.",icon:"Heart",gradient:"from-rose-600 to-pink-700",keyOutcomes:["Feel emotions without reactivity","Locate emotions in the body precisely","Understand emotional triggers and their roots","Transform emotional energy consciously"]},{id:"body",name:"The Gut Lens",subtitle:"The Body Knows What the Mind Hides",days:[46,60],description:"Your body stores every unprocessed experience, every suppressed emotion, every fear you refused to feel. The Gut Lens teaches you to listen to somatic intelligence — the wisdom that bypasses the mind entirely. These 15 days will change your relationship with your physical form forever.",icon:"Activity",gradient:"from-amber-600 to-orange-700",keyOutcomes:["Read somatic signals accurately","Release stored tension patterns","Use the body as a truth detector","Integrate body wisdom into daily decisions"]},{id:"patterns",name:"Loops & Samskaras",subtitle:"Breaking the Chains You Cannot See",days:[61,75],description:"You are not free — you are running programs installed by childhood, culture, trauma, and repetition. These 15 days expose your loops: the unconscious patterns that hijack your behavior, relationships, and happiness. Seeing them clearly is the first step to dissolving them.",icon:"Repeat",gradient:"from-red-600 to-rose-700",keyOutcomes:["Identify your top 5 active loops","Understand trigger → reaction → consequence chains","Practice pattern interruption techniques","Begin dissolving one major loop"]},{id:"inquiry",name:"Self-Inquiry",subtitle:"Who Am I? — The Ultimate Question",days:[76,90],description:'Atma Vichara — self-inquiry — is the most powerful tool ever discovered for human liberation. For 15 days, you will go beyond observation into the territory of "Who is observing?" This is where the mind turns inward and dissolves into its source. Neti Neti — not this, not this — strips away everything false.',icon:"Search",gradient:"from-purple-600 to-violet-800",keyOutcomes:[`Practice Ramana Maharshi's "Who Am I?" method`,"Experience neti neti (not this, not this)","Recognize the difference between self and Self","Touch the space of pure awareness"]},{id:"energy",name:"Energy & Chakras",subtitle:"The Subtle Architecture of Consciousness",days:[91,105],description:"Beyond the physical body lies an energy system mapped by yogis thousands of years ago. These 15 days take you through each chakra — not as philosophy but as felt experience. You will learn to sense energy blockages, understand their psychological correlates, and work with prana directly.",icon:"Zap",gradient:"from-emerald-600 to-teal-700",keyOutcomes:["Feel each chakra as lived experience","Map psychological patterns to energy centers","Understand prana and its movement","Clear major energy blockages"]},{id:"integration",name:"The Four Paths",subtitle:"From Practice to Living",days:[106,118],description:"Knowledge without integration is entertainment. These final 13 days weave everything together through the Four Yoga Paths: Jnana (knowledge), Bhakti (devotion), Karma (action), and Raja (meditation). You will discover which path resonates most deeply and how to make consciousness your way of living — not just a practice.",icon:"Compass",gradient:"from-yellow-600 to-amber-700",keyOutcomes:["Experience each of the four yoga paths","Identify your dominant path","Create a personal daily practice blueprint","Transition from student to practitioner"]}];function y(e){return o.find(t=>e>=t.days[0]&&e<=t.days[1])??o[0]}function m(e){const t=y(e),n=t.days[1]-t.days[0]+1,i=e-t.days[0];return Math.round(i/n*100)}function g(e){return Math.round((e-1)/117*100)}const p=[...a,...s,...r,...h,...u,...d,...c,...l];function f(e){return p.find(t=>t.day===e)}export{o as C,p as F,y as a,m as b,g as c,f as g};
